const i=JSON.parse('{"workId":"han-fei-zi","chapter":{"id":"han-fei-zi_ch-22","workId":"han-fei-zi","order":22,"title":"解老","difficulty":4,"estimatedMinutes":24,"passageIds":["han-fei-zi_ch-22_p-1","han-fei-zi_ch-22_p-2","han-fei-zi_ch-22_p-3","han-fei-zi_ch-22_p-4","han-fei-zi_ch-22_p-5","han-fei-zi_ch-22_p-6","han-fei-zi_ch-22_p-7","han-fei-zi_ch-22_p-8","han-fei-zi_ch-22_p-9","han-fei-zi_ch-22_p-10","han-fei-zi_ch-22_p-11","han-fei-zi_ch-22_p-12","han-fei-zi_ch-22_p-13","han-fei-zi_ch-22_p-14","han-fei-zi_ch-22_p-15","han-fei-zi_ch-22_p-16","han-fei-zi_ch-22_p-17","han-fei-zi_ch-22_p-18","han-fei-zi_ch-22_p-19","han-fei-zi_ch-22_p-20","han-fei-zi_ch-22_p-21","han-fei-zi_ch-22_p-22","han-fei-zi_ch-22_p-23","han-fei-zi_ch-22_p-24","han-fei-zi_ch-22_p-25","han-fei-zi_ch-22_p-26","han-fei-zi_ch-22_p-27","han-fei-zi_ch-22_p-28","han-fei-zi_ch-22_p-29","han-fei-zi_ch-22_p-30","han-fei-zi_ch-22_p-31","han-fei-zi_ch-22_p-32"],"tags":["法家","帝王術","法術勢"]},"passages":[{"id":"han-fei-zi_ch-22_p-1","chapterId":"han-fei-zi_ch-22","order":1,"canonicalText":"德者，內也。得者，外也。上德不德，言其神不淫於外也。神不淫於外則身全，身全之謂德。德者，得身也。凡德者，以無為集，以無欲成，以不思安，以不用固。為之慾之，則德無舍，德無舍則不全。用之思之則不固，不固則無功，無功則生於德。德則無德，不德則在有德。故曰：「上德不德，是以有德。」","sentenceIds":["han-fei-zi_ch-22_p-1_s-1","han-fei-zi_ch-22_p-1_s-2","han-fei-zi_ch-22_p-1_s-3","han-fei-zi_ch-22_p-1_s-4","han-fei-zi_ch-22_p-1_s-5","han-fei-zi_ch-22_p-1_s-6","han-fei-zi_ch-22_p-1_s-7","han-fei-zi_ch-22_p-1_s-8","han-fei-zi_ch-22_p-1_s-9","han-fei-zi_ch-22_p-1_s-10","han-fei-zi_ch-22_p-1_s-11"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"德的人或事物，內啊。得的人或事物，外啊。上德不德，言他的神不淫於外啊。神不淫於外則身全，身全的謂德。德的人或事物，得身啊。凡德的人或事物，以無為集，以無欲成，以不思安，以不用固。為的慾的，則德無舍，德無舍則不全。用的思的則不固，不固則無功，無功則生於德。德則無德，不德則在有德。因此韓絕不是子評論說道：上德不德，是以有德。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「德者，內也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「德者，內也。得者，外也。上德不德，言其神不淫於外也。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-2","chapterId":"han-fei-zi_ch-22","order":2,"canonicalText":"所以貴無為無思為虛者，謂其意無所制也。夫無術者，故以無為無思為虛也。夫故以無為無思為虛者，其意常不忘虛，是制於為虛也。虛者，謂其意無所制也。今制於為虛，是不虛也。虛者之無為也，不以無為為有常，不以無為為有常則虛，虛則德盛，德盛之謂上德，故曰：「上德無為而無不為也。」","sentenceIds":["han-fei-zi_ch-22_p-2_s-1","han-fei-zi_ch-22_p-2_s-2","han-fei-zi_ch-22_p-2_s-3","han-fei-zi_ch-22_p-2_s-4","han-fei-zi_ch-22_p-2_s-5","han-fei-zi_ch-22_p-2_s-6","han-fei-zi_ch-22_p-2_s-7"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以貴無為無思為虛的人或事物，謂他的意無所制啊。夫無御臣心術權謀的人或事物，所以以無為無思為虛啊。夫所以以無為無思為虛的人或事物，他的意常不忘虛，是制於為虛啊。虛的人或事物，謂他的意無所制啊。今制於為虛，是不虛啊。虛的人或事物的無為啊，不以無為為有常，不以無為為有常則虛，虛則德盛，德盛的謂上德，因此韓絕不是子評論說道：上德無為而且無不為啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「所以貴無為無思為虛者，謂其意無所制也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「所以貴無為無思為虛者，謂其意無所制也。夫無術者，故以……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-3","chapterId":"han-fei-zi_ch-22","order":3,"canonicalText":"仁者，謂其中心欣然愛人也。其喜人之有福，而惡人之有禍也。生心之所不能已也，非求其報也。故曰：「上仁為之而無以為也。」","sentenceIds":["han-fei-zi_ch-22_p-3_s-1","han-fei-zi_ch-22_p-3_s-2","han-fei-zi_ch-22_p-3_s-3","han-fei-zi_ch-22_p-3_s-4","han-fei-zi_ch-22_p-3_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仁的人或事物，謂他的中心欣然愛人啊。他的喜人的有福，而且惡人的有禍啊。生心的所不能已啊，絕不是求他的報啊。因此韓絕不是子評論說道：上仁為的而且無以為啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「仁者，謂其中心欣然愛人也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「仁者，謂其中心欣然愛人也。其喜人之有福，而惡人之有禍……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-4","chapterId":"han-fei-zi_ch-22","order":4,"canonicalText":"義者，君臣上下之事，父子貴賤之差也，知交朋友之接也，親疏內外之分也。臣事君宜，下懷上宜，子事父宜，賤敬貴宜，知交友朋之相助也宜，親者內而疏者外宜。義者，謂其宜也，宜而為之，故曰：「上義為之而有以為也。」","sentenceIds":["han-fei-zi_ch-22_p-4_s-1","han-fei-zi_ch-22_p-4_s-2","han-fei-zi_ch-22_p-4_s-3","han-fei-zi_ch-22_p-4_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"義的人或事物，君主統治者臣下僚屬上下的事，父子貴賤的差啊，知交朋友的接啊，親疏內外的分啊。臣下僚屬事君主統治者宜，下懷上宜，子事父宜，賤敬貴宜，知交友朋的相助啊宜，親的人或事物內而且疏的人或事物外宜。義的人或事物，謂他的宜啊，宜而且為的，因此韓絕不是子評論說道：上義為的而且有以為啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「義者，君臣上下之事，父子貴賤之差也，知交朋友之接也，親疏內外之分也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「義者，君臣上下之事，父子貴賤之差也，知交朋友之接也，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-5","chapterId":"han-fei-zi_ch-22","order":5,"canonicalText":"禮者，所以貌情也，羣義之文章也，君臣父子之交也，貴賤賢不肖之所以別也。中心懷而不諭，故疾趨卑拜而明之。實心愛而不知，故好言繁辭以信之。禮者，外節之所以諭內也。故曰：「禮以貌情也。」凡人之為外物動也，不知其為身之禮也。眾人之為禮也，以尊他人也，故時勸時衰。君子之為禮，以為其身，以為其身，故神之為上禮，上禮神而眾人貳，故不能相應，不能相應，故曰：「上禮為之而莫之應。」眾人雖貳，聖人之復恭敬盡手足之禮也不衰，故曰：「攘臂而仍之。」道有積而德有功，德者道之功。功有實而實有光，仁者德之光。光有澤而澤有事，義者仁之事也。事有禮而禮有文，禮者義之文也。故曰：「失道而後失德，失德而後失仁，失仁而後失義，失義而後失禮。」","sentenceIds":["han-fei-zi_ch-22_p-5_s-1","han-fei-zi_ch-22_p-5_s-2","han-fei-zi_ch-22_p-5_s-3","han-fei-zi_ch-22_p-5_s-4","han-fei-zi_ch-22_p-5_s-5","han-fei-zi_ch-22_p-5_s-6","han-fei-zi_ch-22_p-5_s-7","han-fei-zi_ch-22_p-5_s-8","han-fei-zi_ch-22_p-5_s-9","han-fei-zi_ch-22_p-5_s-10","han-fei-zi_ch-22_p-5_s-11","han-fei-zi_ch-22_p-5_s-12","han-fei-zi_ch-22_p-5_s-13","han-fei-zi_ch-22_p-5_s-14","han-fei-zi_ch-22_p-5_s-15"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"禮的人或事物，所以貌情啊，羣義的文章啊，君主統治者臣下僚屬父子的交啊，貴賤賢不肖的所以別啊。中心懷而且不諭，所以疾趨卑拜而且明的。實心愛而且不知，所以好言繁辭以信的。禮的人或事物，外節的所以諭內啊。因此韓絕不是子評論說道：禮以貌情啊。凡人的為外物動啊，不知他的為身的禮啊。眾人的為禮啊，以尊他人啊，所以時勸時衰。君主統治者子的為禮，以為他的身，以為他的身，所以神的為上禮，上禮神而且眾人貳，所以不能相應，不能相應，因此韓絕不是子評論說道：上禮為的而且莫的應。眾人雖貳，聖人的復恭敬盡手足的禮啊不衰，因此韓絕不是子評論說道：攘臂而且仍的。道有積而且德有功，德的人或事物道的功。功有實而且實有光，仁的人或事物德的光。光有澤而且澤有事，義的人或事物仁的事啊。事有禮而且禮有文，禮的人或事物義的文啊。因此韓絕不是子評論說道：失道而且後失德，失德而且後失仁，失仁而且後失義，失義而且後失禮。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「禮者，所以貌情也，羣義之文章也，君臣父子之交也，貴賤賢不肖之所以別也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「禮者，所以貌情也，羣義之文章也，君臣父子之交也，貴賤……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-6","chapterId":"han-fei-zi_ch-22","order":6,"canonicalText":"禮為情貌者也，文為質飾者也。夫君子取情而去貌，好質而惡飾。夫恃貌而論情者，其情惡也；須飾而論質者，其質衰也。何以論之？和氏之璧，不飾以五采，隋侯之珠，不飾以銀黃，其質至美，物不足以飾之。夫物之待飾而後行者，其質不美也。是以父子之間，其禮樸而不明，故曰：「禮薄也。」凡物不並盛，陰陽是也。理相奪予，威德是也。實厚者貌薄，父子之禮是也。由是觀之，禮繁者實心衰也。然則為禮者，事通人之樸心者也。眾人之為禮也，人應則輕歡，不應則責怨。今為禮者事通人之樸心，而資之以相責之分，能毋爭乎？有爭則亂，故曰：「禮者，忠信之薄也，而亂之首乎。」","sentenceIds":["han-fei-zi_ch-22_p-6_s-1","han-fei-zi_ch-22_p-6_s-2","han-fei-zi_ch-22_p-6_s-3","han-fei-zi_ch-22_p-6_s-4","han-fei-zi_ch-22_p-6_s-5","han-fei-zi_ch-22_p-6_s-6","han-fei-zi_ch-22_p-6_s-7","han-fei-zi_ch-22_p-6_s-8","han-fei-zi_ch-22_p-6_s-9","han-fei-zi_ch-22_p-6_s-10","han-fei-zi_ch-22_p-6_s-11","han-fei-zi_ch-22_p-6_s-12","han-fei-zi_ch-22_p-6_s-13","han-fei-zi_ch-22_p-6_s-14","han-fei-zi_ch-22_p-6_s-15","han-fei-zi_ch-22_p-6_s-16","han-fei-zi_ch-22_p-6_s-17"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"禮為情貌的人或事物啊，文為質飾的人或事物啊。夫君主統治者子取情而且去貌，好質而且惡飾。夫恃貌而且論情的人或事物，他的情惡啊；須飾而且論質的人或事物，他的質衰啊。何以論的？和氏的璧，不飾以五采，隋侯的珠，不飾以銀黃，他的質至美，物不足以飾的。夫物的待飾而且後行的人或事物，他的質不美啊。是以父子的間，他的禮樸而且不明，因此韓絕不是子評論說道：禮薄啊。凡物不並盛，陰陽是啊。理相奪予，威德是啊。實厚的人或事物貌薄，父子的禮是啊。由是觀的，禮繁的人或事物實心衰啊。然則為禮的人或事物，事通人的樸心的人或事物啊。眾人的為禮啊，人應則輕歡，不應則責怨。今為禮的人或事物事通人的樸心，而且資的以相責的分，能毋爭乎？有爭則亂，因此韓絕不是子評論說道：禮的人或事物，忠信的薄啊，而且亂的首乎。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「禮為情貌者也，文為質飾者也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「禮為情貌者也，文為質飾者也。夫君子取情而去貌，好質而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-7","chapterId":"han-fei-zi_ch-22","order":7,"canonicalText":"先物行先理動之謂前識，前識者，無緣而忘意度也。何以論之？詹何坐，弟子侍，有牛鳴於門外，弟子曰：「是黑牛也而白題。」詹何曰：「然，是黑牛也，而白在其角。」使人視之，果黑牛而以布裹其角。以詹子之術，嬰眾人之心，華焉殆矣，故曰「道之華也」。嘗試釋詹子之察，而使五尺之愚童子視之，亦知其黑牛而以布裹其角也。故以詹子之察，苦心傷神，而後與五尺之愚童子同功，是以曰「愚之首也」。故曰：「前識者道之華也，而愚之首也。」","sentenceIds":["han-fei-zi_ch-22_p-7_s-1","han-fei-zi_ch-22_p-7_s-2","han-fei-zi_ch-22_p-7_s-3","han-fei-zi_ch-22_p-7_s-4","han-fei-zi_ch-22_p-7_s-5","han-fei-zi_ch-22_p-7_s-6","han-fei-zi_ch-22_p-7_s-7","han-fei-zi_ch-22_p-7_s-8","han-fei-zi_ch-22_p-7_s-9","han-fei-zi_ch-22_p-7_s-10"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"先物行先理動的謂前識，前識的人或事物，無緣而且忘意度啊。何以論的？詹何坐，弟子侍，有牛鳴於門外，弟子說道：是黑牛啊而且白題。詹何說道：然，是黑牛啊，而且白在他的角。使人視的，果黑牛而且以布裹他的角。以詹子的御臣心術權謀，嬰眾人的心，華焉殆矣，因此韓絕不是子評論說道：道的華啊。嘗試釋詹子的察，而且使五尺的愚童子視的，亦知他的黑牛而且以布裹他的角啊。所以以詹子的察，苦心傷神，而且後與五尺的愚童子同功，是以說道：愚的首啊。因此韓絕不是子評論說道：前識的人或事物道的華啊，而且愚的首啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「先物行先理動之謂前識，前識者，無緣而忘意度也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「先物行先理動之謂前識，前識者，無緣而忘意度也。何以論……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-8","chapterId":"han-fei-zi_ch-22","order":8,"canonicalText":"所謂大丈夫者，謂其智之大也。所謂處其厚不處其薄者，行情實而去禮貌也。所謂處其實不處其華者，必緣理不徑絕也。所謂去彼取此者，去貌徑絕而取緣理好情實也。故曰：「去彼取此。」","sentenceIds":["han-fei-zi_ch-22_p-8_s-1","han-fei-zi_ch-22_p-8_s-2","han-fei-zi_ch-22_p-8_s-3","han-fei-zi_ch-22_p-8_s-4","han-fei-zi_ch-22_p-8_s-5","han-fei-zi_ch-22_p-8_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所謂大丈夫的人或事物，謂他的智的大啊。所謂處他的厚不處他的薄的人或事物，行情實而且去禮貌啊。所謂處他的實不處他的華的人或事物，必緣理不徑絕啊。所謂去彼取此的人或事物，去貌徑絕而且取緣理好情實啊。因此韓絕不是子評論說道：去彼取此。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「所謂大丈夫者，謂其智之大也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「所謂大丈夫者，謂其智之大也。所謂處其厚不處其薄者，行……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-9","chapterId":"han-fei-zi_ch-22","order":9,"canonicalText":"人有禍則心畏恐，心畏恐則行端直，行端直則思慮熟，思慮熟則得事理，行端直則無禍害，無禍害則盡天年，得事理則必成功，盡天年則全而壽，必成功則富與貴，全壽富貴之謂福。而福本於有禍，故曰：「禍兮福之所倚。」以成其功也。","sentenceIds":["han-fei-zi_ch-22_p-9_s-1","han-fei-zi_ch-22_p-9_s-2","han-fei-zi_ch-22_p-9_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人有禍則心畏恐，心畏恐則行端直，行端直則思慮熟，思慮熟則得事理，行端直則無禍害，無禍害則盡天年，得事理則必成功，盡天年則全而且壽，必成功則富與貴，全壽富貴的謂福。而且福本於有禍，因此韓絕不是子評論說道：禍兮福的所倚。以成他的功啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人有禍則心畏恐，心畏恐則行端直，行端直則思慮熟，思慮熟則得事理，行端直則無禍害，無禍害則盡天年，得事理則必成功，盡天年則全而壽，必成功則富與貴，全壽富貴之謂福」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人有禍則心畏恐，心畏恐則行端直，行端直則思慮熟，思慮……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-10","chapterId":"han-fei-zi_ch-22","order":10,"canonicalText":"人有福則富貴至，富貴至則衣食美，衣食美則驕心生，驕心生則行邪僻而動棄理，行邪僻則身死夭，動棄理則無成功。夫內有死夭之難，而外無成功之名者，大禍也。而禍本生於有福，故曰：「福兮禍之所伏」。","sentenceIds":["han-fei-zi_ch-22_p-10_s-1","han-fei-zi_ch-22_p-10_s-2","han-fei-zi_ch-22_p-10_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人有福則富貴至，富貴至則衣食美，衣食美則驕心生，驕心生則行邪僻而且動棄理，行邪僻則身死夭，動棄理則無成功。夫內有死夭的難，而且外無成功的名的人或事物，大禍啊。而且禍本生於有福，因此韓絕不是子評論說道：福兮禍的所伏。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人有福則富貴至，富貴至則衣食美，衣食美則驕心生，驕心生則行邪僻而動棄理，行邪僻則身死夭，動棄理則無成功」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人有福則富貴至，富貴至則衣食美，衣食美則驕心生，驕心……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-11","chapterId":"han-fei-zi_ch-22","order":11,"canonicalText":"夫緣道理以從事者無不能成。無不能成者，大能成天子之勢尊，而小易得卿相將軍之賞祿。夫棄道理而忘舉動者，雖上有天子諸侯之勢尊，而下有猗頓、陶朱、卜祝之富，猶失其民人而亡其財資也。眾人之輕棄道理而易忘舉動者，不知其禍福之深大而道闊遠若是也，故諭人曰：「熟知其極。」人莫不欲富貴全壽，而未有能免於貧賤死夭之禍也，心欲富貴全壽，而今貧賤死夭，是不能至於其所欲至也。凡失其所欲之路而妄行者之謂迷，迷則不能至於其所欲至矣。今眾人之不能至於其所欲至，故曰「迷」。眾人之所不能至於其所欲至也，自天地之剖判以至於今，故曰：「人之迷也，其日故以久矣。」","sentenceIds":["han-fei-zi_ch-22_p-11_s-1","han-fei-zi_ch-22_p-11_s-2","han-fei-zi_ch-22_p-11_s-3","han-fei-zi_ch-22_p-11_s-4","han-fei-zi_ch-22_p-11_s-5","han-fei-zi_ch-22_p-11_s-6","han-fei-zi_ch-22_p-11_s-7","han-fei-zi_ch-22_p-11_s-8","han-fei-zi_ch-22_p-11_s-9"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫緣道理以從事的人或事物無不能成。無不能成的人或事物，大能成天子的至高權力威勢尊，而且小易得卿相將軍的賞賜恩惠祿。夫棄道理而且忘舉動的人或事物，雖上有天子諸侯的至高權力威勢尊，而且下有猗頓、陶朱、卜祝的富，猶失他的民人而且亡他的財資啊。眾人的輕棄道理而且易忘舉動的人或事物，不知他的禍福的深大而且道闊遠若是啊，所以諭人說道：熟知他的極。人莫不欲富貴全壽，而且未有能免於貧賤死夭的禍啊，心欲富貴全壽，而且今貧賤死夭，是不能至於他的所欲至啊。凡失他的所欲的路而且妄行的人或事物的謂迷，迷則不能至於他的所欲至矣。今眾人的不能至於他的所欲至，因此韓絕不是子評論說道：迷。眾人的所不能至於他的所欲至啊，自天地的剖判以至於今，因此韓絕不是子評論說道：人的迷啊，他的日所以以久矣。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「夫緣道理以從事者無不能成」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「夫緣道理以從事者無不能成。無不能成者，大能成天子之勢……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-12","chapterId":"han-fei-zi_ch-22","order":12,"canonicalText":"所謂方者，內外相應也，言行相稱也。所謂廉者，必生死之命也，輕恬資財也。所謂直者，義必公正，公心不偏黨也。所謂光者，官爵尊貴，衣裘壯麗也。今有道之士，雖中外信順，不以誹謗窮墮；雖死節輕財，不以侮罷羞貪；雖義端不黨，不以去邪罪私；雖勢尊衣美，不以誇賤欺貧。其故何也？使失路者而肯聽習問知，即不成迷也。今眾人之所以欲成功而反為敗者，生於不知道理而不肯問知而聽能。眾人不肯問知聽能，而聖人強以其禍敗適之，則怨。眾人多而聖人寡，寡之不勝眾，數也。今舉動而與天下之為讎，非全身長生之道也，是以行軌節而舉之也。故曰：「方而不割，廉而不劌，直而不肆，光而不耀。」","sentenceIds":["han-fei-zi_ch-22_p-12_s-1","han-fei-zi_ch-22_p-12_s-2","han-fei-zi_ch-22_p-12_s-3","han-fei-zi_ch-22_p-12_s-4","han-fei-zi_ch-22_p-12_s-5","han-fei-zi_ch-22_p-12_s-6","han-fei-zi_ch-22_p-12_s-7","han-fei-zi_ch-22_p-12_s-8","han-fei-zi_ch-22_p-12_s-9","han-fei-zi_ch-22_p-12_s-10","han-fei-zi_ch-22_p-12_s-11","han-fei-zi_ch-22_p-12_s-12","han-fei-zi_ch-22_p-12_s-13","han-fei-zi_ch-22_p-12_s-14","han-fei-zi_ch-22_p-12_s-15","han-fei-zi_ch-22_p-12_s-16"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所謂方的人或事物，內外相應啊，言行相稱啊。所謂廉的人或事物，必生死的命啊，輕恬資財啊。所謂直的人或事物，義必公正，公心不偏黨啊。所謂光的人或事物，官爵尊貴，衣裘壯麗啊。今有道的士，雖中外信順，不以誹謗窮墮；雖死節輕財，不以侮罷羞貪；雖義端不黨，不以去邪罪私；雖至高權力威勢尊衣美，不以誇賤欺貧。他的所以何啊？使失路的人或事物而且肯聽習問知，即不成迷啊。今眾人的所以欲成功而且反為敗的人或事物，生於不知道理而且不肯問知而且聽能。眾人不肯問知聽能，而且聖人強以他的禍敗適的，則怨。眾人多而且聖人寡，寡的不勝眾，數啊。今舉動而且與天下的為讎，絕不是全身長生的道啊，是以行軌節而且舉的啊。因此韓絕不是子評論說道：方而且不割，廉而且不劌，直而且不肆，光而且不耀。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「所謂方者，內外相應也，言行相稱也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「所謂方者，內外相應也，言行相稱也。所謂廉者，必生死之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-13","chapterId":"han-fei-zi_ch-22","order":13,"canonicalText":"聰明睿智天也，動靜思慮人也。人也者，乘於天明以視，寄於天聰以聽，託於天智以思慮。故視強則目不明，聽甚則耳不聰，思慮過度則智識亂。目不明則不能決黑白之分，耳不聰則不能別清濁之聲，智識亂則不能審得失之地。目不能決黑白之色則謂之盲，耳不能別清濁之聲則謂之聾，心不能審得失之地則謂之狂。盲則不能避晝日之險，聾則不能知雷霆之害，狂則不能免人間法令之禍。書之所謂治人者，適動靜之節，省思慮之費也。所謂事天者，不極聰明之力，不盡智識之任。苟極盡則費神多，費神多則盲聾悖狂之禍至，是以嗇之。嗇之者，愛其精神，嗇其智識也。故曰：「治人事天莫如嗇。」","sentenceIds":["han-fei-zi_ch-22_p-13_s-1","han-fei-zi_ch-22_p-13_s-2","han-fei-zi_ch-22_p-13_s-3","han-fei-zi_ch-22_p-13_s-4","han-fei-zi_ch-22_p-13_s-5","han-fei-zi_ch-22_p-13_s-6","han-fei-zi_ch-22_p-13_s-7","han-fei-zi_ch-22_p-13_s-8","han-fei-zi_ch-22_p-13_s-9","han-fei-zi_ch-22_p-13_s-10","han-fei-zi_ch-22_p-13_s-11","han-fei-zi_ch-22_p-13_s-12"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"聰明睿智天啊，動靜思慮人啊。人啊的人或事物，乘於天明以視，寄於天聰以聽，託於天智以思慮。所以視強則目不明，聽甚則耳不聰，思慮過度則智識亂。目不明則不能決黑白的分，耳不聰則不能別清濁的聲，智識亂則不能審得失的地。目不能決黑白的色則謂的盲，耳不能別清濁的聲則謂的聾，心不能審得失的地則謂的狂。盲則不能避晝日的險，聾則不能知雷霆的害，狂則不能免人間國家法度法規令的禍。書的所謂治人的人或事物，適動靜的節，省思慮的費啊。所謂事天的人或事物，不極聰明的力，不盡智識的任。苟極盡則費神多，費神多則盲聾悖狂的禍至，是以嗇的。嗇的的人或事物，愛他的精神，嗇他的智識啊。因此韓絕不是子評論說道：治人事天莫如嗇。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「聰明睿智天也，動靜思慮人也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「聰明睿智天也，動靜思慮人也。人也者，乘於天明以視，寄……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-14","chapterId":"han-fei-zi_ch-22","order":14,"canonicalText":"眾人之用神也躁，躁則多費，多費之謂侈。聖人之用神也靜，靜則少費，少費之謂嗇。嗇之謂術也生於道理。夫能嗇也，是從於道而服於理者也。眾人離於患，陷於禍，猶未知退，而不服從道理。聖人雖未見禍患之形，虛無服從於道理，以稱蚤服。故曰：「夫謂嗇，是以蚤服。」","sentenceIds":["han-fei-zi_ch-22_p-14_s-1","han-fei-zi_ch-22_p-14_s-2","han-fei-zi_ch-22_p-14_s-3","han-fei-zi_ch-22_p-14_s-4","han-fei-zi_ch-22_p-14_s-5","han-fei-zi_ch-22_p-14_s-6","han-fei-zi_ch-22_p-14_s-7","han-fei-zi_ch-22_p-14_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"眾人的用神啊躁，躁則多費，多費的謂侈。聖人的用神啊靜，靜則少費，少費的謂嗇。嗇的謂御臣心術權謀啊生於道理。夫能嗇啊，是從於道而且服於理的人或事物啊。眾人離於患，陷於禍，猶未知退，而且不服從道理。聖人雖未見禍患的形，虛無服從於道理，以稱蚤服。因此韓絕不是子評論說道：夫謂嗇，是以蚤服。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「眾人之用神也躁，躁則多費，多費之謂侈」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「眾人之用神也躁，躁則多費，多費之謂侈。聖人之用神也靜……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-15","chapterId":"han-fei-zi_ch-22","order":15,"canonicalText":"知治人者其思慮靜，知事天者其孔竅虛。思慮靜，故德不去。孔竅虛，則和氣日入。故曰：「重積德。」夫能令故德不去，新和氣日至者，蚤服者也。故曰：「蚤服是謂重積德。」積德而後神靜，神靜而後和多，和多而後計得，計得而後能御萬物，能御萬物則戰易勝敵，戰易勝敵而論必蓋世，論必蓋世，故曰「無不克」。無不克本於重積德，故曰「重積德則無不克」。戰易勝敵則兼有天下，論必蓋世則民人從。進兼天下而退從民人，其術遠，則眾人莫見其端末。莫見其端末，是以莫知其極，故曰：「無不克則莫知其極。」","sentenceIds":["han-fei-zi_ch-22_p-15_s-1","han-fei-zi_ch-22_p-15_s-2","han-fei-zi_ch-22_p-15_s-3","han-fei-zi_ch-22_p-15_s-4","han-fei-zi_ch-22_p-15_s-5","han-fei-zi_ch-22_p-15_s-6","han-fei-zi_ch-22_p-15_s-7","han-fei-zi_ch-22_p-15_s-8","han-fei-zi_ch-22_p-15_s-9","han-fei-zi_ch-22_p-15_s-10","han-fei-zi_ch-22_p-15_s-11","han-fei-zi_ch-22_p-15_s-12"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"知治人的人或事物他的思慮靜，知事天的人或事物他的孔竅虛。思慮靜，所以德不去。孔竅虛，則和氣日入。因此韓絕不是子評論說道：重積德。夫能令所以德不去，新和氣日至的人或事物，蚤服的人或事物啊。因此韓絕不是子評論說道：蚤服是謂重積德。積德而且後神靜，神靜而且後和多，和多而且後計得，計得而且後能御萬物，能御萬物則戰易勝敵，戰易勝敵而且論必蓋世，論必蓋世，因此韓絕不是子評論說道：無不克。無不克本於重積德，因此韓絕不是子評論說道：重積德則無不克。戰易勝敵則兼有天下，論必蓋世則民人從。進兼天下而且退從民人，他的御臣心術權謀遠，則眾人莫見他的端末。莫見他的端末，是以莫知他的極，因此韓絕不是子評論說道：無不克則莫知他的極。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 15 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「知治人者其思慮靜，知事天者其孔竅虛」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「知治人者其思慮靜，知事天者其孔竅虛。思慮靜，故德不去……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-16","chapterId":"han-fei-zi_ch-22","order":16,"canonicalText":"凡有國而後亡之，有身而後殃之，不可謂能有其國能保其身。夫能有其國、必能安其社稷，能保其身、必能終其天年，而後可謂能有其國、能保其身矣。夫能有其國、保其身者必且體道，體道則其智深，其智深則其會遠，其會遠眾人莫能見其所極。唯夫能令人不見其事極，不見事極者為保其身、有其國，故曰：「莫知其極；莫知其極，則可以有國。」","sentenceIds":["han-fei-zi_ch-22_p-16_s-1","han-fei-zi_ch-22_p-16_s-2","han-fei-zi_ch-22_p-16_s-3","han-fei-zi_ch-22_p-16_s-4","han-fei-zi_ch-22_p-16_s-5","han-fei-zi_ch-22_p-16_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡有國而且後亡的，有身而且後殃的，不可謂能有他的國能保他的身。夫能有他的國、必能安他的社稷，能保他的身、必能終他的天年，而且後可謂能有他的國、能保他的身矣。夫能有他的國、保他的身的人或事物必且體道，體道則他的智深，他的智深則他的會遠，他的會遠眾人莫能見他的所極。唯夫能令人不見他的事極，不見事極的人或事物為保他的身、有他的國，因此韓絕不是子評論說道：莫知他的極；莫知他的極，則可以有國。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 16 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「凡有國而後亡之，有身而後殃之，不可謂能有其國能保其身」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「凡有國而後亡之，有身而後殃之，不可謂能有其國能保其身……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-17","chapterId":"han-fei-zi_ch-22","order":17,"canonicalText":"所謂有國之母，母者，道也，道也者生於所以有國之術，所以有國之術，故謂之有國之母。夫道以與世周旋者，其建生也長，持祿也久，故曰：「有國之母，可以長久。」樹木有曼根，有直根。根者，書之所謂柢也。柢也者，木之所以建生也；曼根者，木之所以持生也。德也者，人之所以建生也；祿也者，人之所以持生也。今建於理者其持祿也久，故曰：「深其根。」體其道者，其生日長，故曰：「固其柢。」柢固則生長，根深則視久，故曰：「深其根，固其柢，長生久視之道也。」","sentenceIds":["han-fei-zi_ch-22_p-17_s-1","han-fei-zi_ch-22_p-17_s-2","han-fei-zi_ch-22_p-17_s-3","han-fei-zi_ch-22_p-17_s-4","han-fei-zi_ch-22_p-17_s-5","han-fei-zi_ch-22_p-17_s-6","han-fei-zi_ch-22_p-17_s-7","han-fei-zi_ch-22_p-17_s-8","han-fei-zi_ch-22_p-17_s-9","han-fei-zi_ch-22_p-17_s-10","han-fei-zi_ch-22_p-17_s-11","han-fei-zi_ch-22_p-17_s-12"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所謂有國的母，母的人或事物，道啊，道啊的人或事物生於所以有國的御臣心術權謀，所以有國的御臣心術權謀，所以謂的有國的母。夫道以與世周旋的人或事物，他的建生啊長，持祿啊久，因此韓絕不是子評論說道：有國的母，可以長久。樹木有曼根，有直根。根的人或事物，書的所謂柢啊。柢啊的人或事物，木的所以建生啊；曼根的人或事物，木的所以持生啊。德啊的人或事物，人的所以建生啊；祿啊的人或事物，人的所以持生啊。今建於理的人或事物他的持祿啊久，因此韓絕不是子評論說道：深他的根。體他的道的人或事物，他的生日長，因此韓絕不是子評論說道：固他的柢。柢固則生長，根深則視久，因此韓絕不是子評論說道：深他的根，固他的柢，長生久視的道啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 17 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「所謂有國之母，母者，道也，道也者生於所以有國之術，所以有國之術，故謂之有國之母」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「所謂有國之母，母者，道也，道也者生於所以有國之術，所……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-18","chapterId":"han-fei-zi_ch-22","order":18,"canonicalText":"工人數變業則失其功，作者數搖徙則亡其功。一人之作，日亡半日，十日則亡五人之功矣。萬人之作，日亡半日，十日則亡五萬人之功矣。然則數變業者，其人彌眾，其虧彌大矣。凡法令更則利害易，利害易則民務變，務變之謂變業。故以理觀之，事大眾而數搖之則少成功，藏大器而數徙之則多敗傷，烹小鮮而數撓之則賊其澤，治大國而數變法則民苦之，是以有道之君貴靜，不重變法，故曰：「治大國者若烹小鮮。」","sentenceIds":["han-fei-zi_ch-22_p-18_s-1","han-fei-zi_ch-22_p-18_s-2","han-fei-zi_ch-22_p-18_s-3","han-fei-zi_ch-22_p-18_s-4","han-fei-zi_ch-22_p-18_s-5","han-fei-zi_ch-22_p-18_s-6","han-fei-zi_ch-22_p-18_s-7"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"工人數變業則失他的功，作的人或事物數搖徙則亡他的功。一人的作，日亡半日，十日則亡五人的功矣。萬人的作，日亡半日，十日則亡五萬人的功矣。然則數變業的人或事物，他的人彌眾，他的虧彌大矣。凡國家法度法規令更則利害易，利害易則民務變，務變的謂變業。所以以理觀的，事大眾而且數搖的則少成功，藏大器而且數徙的則多敗傷，烹小鮮而且數撓的則賊他的澤，治大國而且數變國家法度法規則民苦的，是以有道的君主統治者貴靜，不重變國家法度法規，因此韓絕不是子評論說道：治大國的人或事物若烹小鮮。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 18 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「工人數變業則失其功，作者數搖徙則亡其功」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「工人數變業則失其功，作者數搖徙則亡其功。一人之作，日……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-19","chapterId":"han-fei-zi_ch-22","order":19,"canonicalText":"人處疾則貴醫，有禍則畏鬼。聖人在上則民少欲，民少欲則血氣治，而舉動理則少禍害。夫內無痤疽癉痔之害，而外無刑罰法誅之禍者，其輕恬鬼也甚，故曰：「以道蒞天下，其鬼不神。」治世之民不與鬼神相害也，故曰：「非其鬼不神也，其神不傷人也。」鬼崇也疾人之謂鬼傷人，人逐除之之謂人傷鬼也；民犯法令之謂民傷上，上刑戮民之謂上傷民；民不犯法則上亦不行刑，上不行刑之謂上不傷人；故曰：「聖人亦不傷民。」上不與民相害，而人不與鬼相傷，故曰：「兩不相傷。」民不敢犯法，則上內不用刑罰，而外不事利其產業，上內不用刑罰、而外不事利其產業則民蕃息，民蕃息而畜積盛，民蕃息而畜積盛之謂有德。凡所謂崇者，魂魄去而精神亂，精神亂則無德。鬼不崇人則魂魄不去，魂魄不去而精神不亂，精神不亂之謂有德。上盛畜積，而鬼不亂其精神，則德盡在於民矣。故曰：「兩不相傷，則德交歸焉。」言其德上下交盛而俱歸於民也。","sentenceIds":["han-fei-zi_ch-22_p-19_s-1","han-fei-zi_ch-22_p-19_s-2","han-fei-zi_ch-22_p-19_s-3","han-fei-zi_ch-22_p-19_s-4","han-fei-zi_ch-22_p-19_s-5","han-fei-zi_ch-22_p-19_s-6","han-fei-zi_ch-22_p-19_s-7","han-fei-zi_ch-22_p-19_s-8","han-fei-zi_ch-22_p-19_s-9","han-fei-zi_ch-22_p-19_s-10","han-fei-zi_ch-22_p-19_s-11","han-fei-zi_ch-22_p-19_s-12","han-fei-zi_ch-22_p-19_s-13","han-fei-zi_ch-22_p-19_s-14","han-fei-zi_ch-22_p-19_s-15"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人處疾則貴醫，有禍則畏鬼。聖人在上則民少欲，民少欲則血氣治，而且舉動理則少禍害。夫內無痤疽癉痔的害，而且外無刑刑罰制裁國家法度法規誅的禍的人或事物，他的輕恬鬼啊甚，因此韓絕不是子評論說道：以道蒞天下，他的鬼不神。治世的民不與鬼神相害啊，因此韓絕不是子評論說道：絕不是他的鬼不神啊，他的神不傷人啊。鬼崇啊疾人的謂鬼傷人，人逐除的的謂人傷鬼啊；民犯國家法度法規令的謂民傷上，上刑戮民的謂上傷民；民不犯國家法度法規則上亦不行刑，上不行刑的謂上不傷人；因此韓絕不是子評論說道：聖人亦不傷民。上不與民相害，而且人不與鬼相傷，因此韓絕不是子評論說道：兩不相傷。民不敢犯國家法度法規，則上內不用刑刑罰制裁，而且外不事利他的產業，上內不用刑刑罰制裁、而且外不事利他的產業則民蕃息，民蕃息而且畜積盛，民蕃息而且畜積盛的謂有德。凡所謂崇的人或事物，魂魄去而且精神亂，精神亂則無德。鬼不崇人則魂魄不去，魂魄不去而且精神不亂，精神不亂的謂有德。上盛畜積，而且鬼不亂他的精神，則德盡在於民矣。因此韓絕不是子評論說道：兩不相傷，則德交歸焉。言他的德上下交盛而且俱歸於民啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 19 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人處疾則貴醫，有禍則畏鬼」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人處疾則貴醫，有禍則畏鬼。聖人在上則民少欲，民少欲則……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-20","chapterId":"han-fei-zi_ch-22","order":20,"canonicalText":"有道之君，外無怨讎於鄰敵，而內有德澤於人民。夫外無怨讎於鄰敵者，其遇諸侯也外有禮義。內有德澤於人民者，其治人事也務本。遇諸侯有禮義則役希起，治民事務本則淫奢止。凡馬之所以大用者，外供甲兵，而內給淫奢也。今有道之君，外希用甲兵，而內禁淫奢。上不事馬於戰鬥逐北，而民不以馬遠淫通物，所積力唯田疇，積力於田疇必且糞灌，故曰：「天下有道，卻走馬以糞也。」","sentenceIds":["han-fei-zi_ch-22_p-20_s-1","han-fei-zi_ch-22_p-20_s-2","han-fei-zi_ch-22_p-20_s-3","han-fei-zi_ch-22_p-20_s-4","han-fei-zi_ch-22_p-20_s-5","han-fei-zi_ch-22_p-20_s-6","han-fei-zi_ch-22_p-20_s-7","han-fei-zi_ch-22_p-20_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"有道的君主統治者，外無怨讎於鄰敵，而且內有德澤於人民。夫外無怨讎於鄰敵的人或事物，他的遇諸侯啊外有禮義。內有德澤於人民的人或事物，他的治人事啊務本。遇諸侯有禮義則役希起，治民事務本則淫奢止。凡馬的所以大用的人或事物，外供甲兵，而且內給淫奢啊。今有道的君主統治者，外希用甲兵，而且內禁淫奢。上不事馬於戰鬥逐北，而且民不以馬遠淫通物，所積力唯田疇，積力於田疇必且糞灌，因此韓絕不是子評論說道：天下有道，卻走馬以糞啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 20 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「有道之君，外無怨讎於鄰敵，而內有德澤於人民」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「有道之君，外無怨讎於鄰敵，而內有德澤於人民。夫外無怨……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-21","chapterId":"han-fei-zi_ch-22","order":21,"canonicalText":"人君者無道，則內暴虐其民，而外侵欺其鄰國。內暴虐則民產絕，外侵欺則兵數起。民產絕則畜生少，兵數起則士卒盡。畜生少則戎馬乏，士卒盡則軍危殆。戎馬乏則將馬出，軍危殆則近臣役。馬者，軍之大用；郊者，言其近也。今所以給軍之具於將馬近臣，故曰：「天下無道，戎馬生於郊矣。」","sentenceIds":["han-fei-zi_ch-22_p-21_s-1","han-fei-zi_ch-22_p-21_s-2","han-fei-zi_ch-22_p-21_s-3","han-fei-zi_ch-22_p-21_s-4","han-fei-zi_ch-22_p-21_s-5","han-fei-zi_ch-22_p-21_s-6","han-fei-zi_ch-22_p-21_s-7","han-fei-zi_ch-22_p-21_s-8","han-fei-zi_ch-22_p-21_s-9"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人君主統治者的人或事物無道，則內暴虐他的民，而且外侵欺他的鄰國。內暴虐則民產絕，外侵欺則兵數起。民產絕則畜生少，兵數起則士卒盡。畜生少則戎馬乏，士卒盡則軍危殆。戎馬乏則將馬出，軍危殆則近臣下僚屬役。馬的人或事物，軍的大用；郊的人或事物，言他的近啊。今所以給軍的具於將馬近臣下僚屬，因此韓絕不是子評論說道：天下無道，戎馬生於郊矣。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 21 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人君者無道，則內暴虐其民，而外侵欺其鄰國」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人君者無道，則內暴虐其民，而外侵欺其鄰國。內暴虐則民……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-22","chapterId":"han-fei-zi_ch-22","order":22,"canonicalText":"人有欲則計會亂，計會亂而有欲甚，有欲甚則邪心勝，邪心勝則事經絕，事經絕則禍難生。由是觀之，禍難生於邪心，邪心誘於可欲。可欲之類，進則教良民為姦，退則令善人有禍。姦起則上侵弱君，禍至則民人多傷。然則可欲之類，上侵弱君而下傷人民。夫上侵弱君而下傷人民者，大罪也。故曰：「禍莫大於可欲。」是以聖人不引五色，不淫於聲樂，明君賤玩好而去淫麗。人無毛羽，不衣則不犯寒。上不屬天，而下不著地，以腸胃為根本，不食則不能活。是以不免於欲利之心，欲利之心不除，其身之憂也。故聖人衣足以犯寒，食足以充虛，則不憂矣。眾人則不然，大為諸侯，小餘千金之資，其欲得之憂不除也，胥靡有免，死罪時活，今不知足者之憂，終身不解，故曰：「禍莫大於不知足。」故欲利甚於憂，憂則疾生，疾生而智慧衰，智慧衰則失度量，失度量則妄舉動，妄舉動則禍害至，禍害至而疾嬰內，疾嬰內則痛禍薄外，痛禍薄外則苦痛雜於腸胃之間，苦痛雜於腸胃之間則傷人也憯，憯則退而自咎，退而自咎也生於欲利，故曰：「咎莫憯於欲利。」","sentenceIds":["han-fei-zi_ch-22_p-22_s-1","han-fei-zi_ch-22_p-22_s-2","han-fei-zi_ch-22_p-22_s-3","han-fei-zi_ch-22_p-22_s-4","han-fei-zi_ch-22_p-22_s-5","han-fei-zi_ch-22_p-22_s-6","han-fei-zi_ch-22_p-22_s-7","han-fei-zi_ch-22_p-22_s-8","han-fei-zi_ch-22_p-22_s-9","han-fei-zi_ch-22_p-22_s-10","han-fei-zi_ch-22_p-22_s-11","han-fei-zi_ch-22_p-22_s-12","han-fei-zi_ch-22_p-22_s-13","han-fei-zi_ch-22_p-22_s-14","han-fei-zi_ch-22_p-22_s-15"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人有欲則計會亂，計會亂而且有欲甚，有欲甚則邪心勝，邪心勝則事經絕，事經絕則禍難生。由是觀的，禍難生於邪心，邪心誘於可欲。可欲的類，進則教良民為姦，退則令善人有禍。姦起則上侵弱君主統治者，禍至則民人多傷。然則可欲的類，上侵弱君主統治者而且下傷人民。夫上侵弱君主統治者而且下傷人民的人或事物，大罪啊。因此韓絕不是子評論說道：禍莫大於可欲。是以聖人不引五色，不淫於聲樂，明君主統治者賤玩好而且去淫麗。人無毛羽，不衣則不犯寒。上不屬天，而且下不著地，以腸胃為根本，不食則不能活。是以不免於欲利的心，欲利的心不除，他的身的憂啊。所以聖人衣足以犯寒，食足以充虛，則不憂矣。眾人則不然，大為諸侯，小餘千金的資，他的欲得的憂不除啊，胥靡有免，死罪時活，今不知足的人或事物的憂，終身不解，因此韓絕不是子評論說道：禍莫大於不知足。所以欲利甚於憂，憂則疾生，疾生而且智慧衰，智慧衰則失度量，失度量則妄舉動，妄舉動則禍害至，禍害至而且疾嬰內，疾嬰內則痛禍薄外，痛禍薄外則苦痛雜於腸胃的間，苦痛雜於腸胃的間則傷人啊憯，憯則退而且自咎，退而且自咎啊生於欲利，因此韓絕不是子評論說道：咎莫憯於欲利。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 22 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人有欲則計會亂，計會亂而有欲甚，有欲甚則邪心勝，邪心勝則事經絕，事經絕則禍難生」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人有欲則計會亂，計會亂而有欲甚，有欲甚則邪心勝，邪心……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-23","chapterId":"han-fei-zi_ch-22","order":23,"canonicalText":"道者，萬物之所然也，萬理之所稽也。理者，成物之文也；道者，萬物之所以成也。故曰：「道，理之者也。」物有理不可以相薄，物有理不可以相薄故理之為物之制。萬物各異理，萬物各異理而道盡。稽萬物之理，故不得不化；不得不化，故無常操；無常操，是以死生氣稟焉，萬智斟酌焉，萬事廢興焉。天得之以高，地得之以藏，維鬥得之以成其威，日月得之以恆其光，五常得之以常其位，列星得之以端其行，四時得之以御其變氣，軒轅得之以擅四方，赤松得之與天地統，聖人得之以成文章。道與堯、舜俱智，與接輿俱狂，與桀、紂俱滅，與湯、武俱昌。以為近乎，遊於四極；以為遠乎，常在吾側；以為暗乎，其光昭昭；以為明乎，其物冥冥；而功成天地，和化雷霆，宇內之物，恃之以成。凡道之情，不制不形，柔弱隨時，與理相應。萬物得之以死，得之以生；萬事得之以敗，得之以成。道譬諸若水，溺者多飲之即死，渴者適飲之即生。譬之若劍戟，愚人以行忿則禍生，聖人以誅暴則福成。故得之以死，得之以生，得之以敗，得之以成。","sentenceIds":["han-fei-zi_ch-22_p-23_s-1","han-fei-zi_ch-22_p-23_s-2","han-fei-zi_ch-22_p-23_s-3","han-fei-zi_ch-22_p-23_s-4","han-fei-zi_ch-22_p-23_s-5","han-fei-zi_ch-22_p-23_s-6","han-fei-zi_ch-22_p-23_s-7","han-fei-zi_ch-22_p-23_s-8","han-fei-zi_ch-22_p-23_s-9","han-fei-zi_ch-22_p-23_s-10","han-fei-zi_ch-22_p-23_s-11","han-fei-zi_ch-22_p-23_s-12","han-fei-zi_ch-22_p-23_s-13","han-fei-zi_ch-22_p-23_s-14","han-fei-zi_ch-22_p-23_s-15","han-fei-zi_ch-22_p-23_s-16","han-fei-zi_ch-22_p-23_s-17","han-fei-zi_ch-22_p-23_s-18","han-fei-zi_ch-22_p-23_s-19","han-fei-zi_ch-22_p-23_s-20","han-fei-zi_ch-22_p-23_s-21","han-fei-zi_ch-22_p-23_s-22"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"道的人或事物，萬物的所然啊，萬理的所稽啊。理的人或事物，成物的文啊；道的人或事物，萬物的所以成啊。因此韓絕不是子評論說道：道，理的的人或事物啊。物有理不可以相薄，物有理不可以相薄所以理的為物的制。萬物各異理，萬物各異理而且道盡。稽萬物的理，所以不得不化；不得不化，所以無常操；無常操，是以死生氣稟焉，萬智斟酌焉，萬事廢興焉。天得的以高，地得的以藏，維鬥得的以成他的威，日月得的以恆他的光，五常得的以常他的位，列星得的以端他的行，四時得的以御他的變氣，軒轅得的以擅四方，赤松得的與天地統，聖人得的以成文章。道與堯、舜俱智，與接輿俱狂，與桀、紂俱滅，與湯、武俱昌。以為近乎，遊於四極；以為遠乎，常在吾側；以為暗乎，他的光昭昭；以為明乎，他的物冥冥；而且功成天地，和化雷霆，宇內的物，恃的以成。凡道的情，不制不形，柔弱隨時，與理相應。萬物得的以死，得的以生；萬事得的以敗，得的以成。道譬諸若水，溺的人或事物多飲的即死，渴的人或事物適飲的即生。譬的若劍戟，愚人以行忿則禍生，聖人以誅暴則福成。所以得的以死，得的以生，得的以敗，得的以成。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 23 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「道者，萬物之所然也，萬理之所稽也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「道者，萬物之所然也，萬理之所稽也。理者，成物之文也；……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-24","chapterId":"han-fei-zi_ch-22","order":24,"canonicalText":"人希見生象也，而得死象之骨，案其圖以想其生也，故諸人之所以意想者皆謂之象也。今道雖不可得聞見，聖人執其見功以處見其形，故曰：「無狀之狀，無物之象。」","sentenceIds":["han-fei-zi_ch-22_p-24_s-1","han-fei-zi_ch-22_p-24_s-2","han-fei-zi_ch-22_p-24_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人希見生象啊，而且得死象的骨，案他的圖以想他的生啊，所以諸人的所以意想的人或事物皆謂的象啊。今道雖不可得聞見，聖人執他的見功以處見他的形，因此韓絕不是子評論說道：無狀的狀，無物的象。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 24 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人希見生象也，而得死象之骨，案其圖以想其生也，故諸人之所以意想者皆謂之象也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人希見生象也，而得死象之骨，案其圖以想其生也，故諸人……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-25","chapterId":"han-fei-zi_ch-22","order":25,"canonicalText":"凡理者，方圓、短長、麤靡、堅脆之分也。故理定而後可得道也。故定理有存亡，有死生，有盛衰。夫物之一存一亡，乍死乍生，初盛而後衰者，不可謂常。唯夫與天地之剖判也具生，至天地之消散也不死不衰者謂常。而常者，無攸易，無定理，無定理非在於常所，是以不可道也。聖人觀其玄虛，用其周行，強字之曰道，然而可論，故曰：「道之可道，非常道也。」","sentenceIds":["han-fei-zi_ch-22_p-25_s-1","han-fei-zi_ch-22_p-25_s-2","han-fei-zi_ch-22_p-25_s-3","han-fei-zi_ch-22_p-25_s-4","han-fei-zi_ch-22_p-25_s-5","han-fei-zi_ch-22_p-25_s-6","han-fei-zi_ch-22_p-25_s-7","han-fei-zi_ch-22_p-25_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡理的人或事物，方圓、短長、麤靡、堅脆的分啊。所以理定而且後可得道啊。所以定理有存亡，有死生，有盛衰。夫物的一存一亡，乍死乍生，初盛而且後衰的人或事物，不可謂常。唯夫與天地的剖判啊具生，至天地的消散啊不死不衰的人或事物謂常。而且常的人或事物，無攸易，無定理，無定理絕不是在於常所，是以不可道啊。聖人觀他的玄虛，用他的周行，強字的說道：道，然而且可論，因此韓絕不是子評論說道：道的可道，絕不是常道啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 25 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「凡理者，方圓、短長、麤靡、堅脆之分也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「凡理者，方圓、短長、麤靡、堅脆之分也。故理定而後可得……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-26","chapterId":"han-fei-zi_ch-22","order":26,"canonicalText":"人始於生而卒於死。始之謂出，卒之謂入，故曰：「出生入死。」人之身三百六十節，四肢，九竅，其大具也。四肢與九竅十有三者，十有三者之動靜盡屬於生焉。屬之謂徒也，故曰：「生之徒也十有三者。」至死也十有三具者皆還而屬之於死，死之徒亦有十三，故曰：「生之徒，十有三；死之徒，十有三。」凡民之生生而生者固動，動盡則損也，而動不止，是損而不止也，損而不止則生盡，生盡之謂死，則十有三具者皆為死死地也。故曰：「民之生，生而動，動皆之死地，之十有三。」是以聖人愛精神而貴處靜，此甚大於兕虎之害。夫兕虎有域，動靜有時，避其域，省其時，則免其兕虎之害矣。民獨知兕虎之有爪角也，而莫知萬物之盡有爪角也，不免於萬物之害。何以論之？時雨降集，曠野閒靜，而以昏晨犯山川，則風露之爪角害之。事上不忠，輕犯禁令，則刑法之爪角害之。處鄉不節，憎愛無度，則爭鬥之爪角害之。嗜慾無限，動靜不節，則痤疽之爪角害之。好用其私智而棄道理，則網羅之爪角害之。兕虎有域，而萬害有原，避其域，塞其原，則免於諸害矣。凡兵革者，所以備害也。重生者雖入軍無忿爭之心，無忿爭之心則無所用救害之備。此非獨謂野處之軍也，聖人之遊世也無害人之心，無害人之心則必無人害，無人害則不備人，故曰：「陸行不遇兕虎。」入山不恃備以救害，故曰：「入軍不備甲兵。」遠諸害，故曰：「兕無所投其角，虎無所錯其爪，兵無所容其刃。」不設備而必無害，天地之道理也。體天地之道，故曰：「無死地焉。」動無死地，而謂之「善攝生」矣。","sentenceIds":["han-fei-zi_ch-22_p-26_s-1","han-fei-zi_ch-22_p-26_s-2","han-fei-zi_ch-22_p-26_s-3","han-fei-zi_ch-22_p-26_s-4","han-fei-zi_ch-22_p-26_s-5","han-fei-zi_ch-22_p-26_s-6","han-fei-zi_ch-22_p-26_s-7","han-fei-zi_ch-22_p-26_s-8","han-fei-zi_ch-22_p-26_s-9","han-fei-zi_ch-22_p-26_s-10","han-fei-zi_ch-22_p-26_s-11","han-fei-zi_ch-22_p-26_s-12","han-fei-zi_ch-22_p-26_s-13","han-fei-zi_ch-22_p-26_s-14","han-fei-zi_ch-22_p-26_s-15","han-fei-zi_ch-22_p-26_s-16","han-fei-zi_ch-22_p-26_s-17","han-fei-zi_ch-22_p-26_s-18","han-fei-zi_ch-22_p-26_s-19","han-fei-zi_ch-22_p-26_s-20","han-fei-zi_ch-22_p-26_s-21","han-fei-zi_ch-22_p-26_s-22","han-fei-zi_ch-22_p-26_s-23","han-fei-zi_ch-22_p-26_s-24","han-fei-zi_ch-22_p-26_s-25","han-fei-zi_ch-22_p-26_s-26","han-fei-zi_ch-22_p-26_s-27"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人始於生而且卒於死。始的謂出，卒的謂入，因此韓絕不是子評論說道：出生入死。人的身三百六十節，四肢，九竅，他的大具啊。四肢與九竅十有三的人或事物，十有三的人或事物的動靜盡屬於生焉。屬的謂徒啊，因此韓絕不是子評論說道：生的徒啊十有三的人或事物。至死啊十有三具的人或事物皆還而且屬的於死，死的徒亦有十三，因此韓絕不是子評論說道：生的徒，十有三；死的徒，十有三。凡民的生生而且生的人或事物固動，動盡則損啊，而且動不止，是損而且不止啊，損而且不止則生盡，生盡的謂死，則十有三具的人或事物皆為死死地啊。因此韓絕不是子評論說道：民的生，生而且動，動皆的死地，的十有三。是以聖人愛精神而且貴處靜，此甚大於兕虎的害。夫兕虎有域，動靜有時，避他的域，省他的時，則免他的兕虎的害矣。民獨知兕虎的有爪角啊，而且莫知萬物的盡有爪角啊，不免於萬物的害。何以論的？時雨降集，曠野閒靜，而且以昏晨犯山川，則風露的爪角害的。事上不忠，輕犯禁令，則刑國家法度法規的爪角害的。處鄉不節，憎愛無度，則爭鬥的爪角害的。嗜慾無限，動靜不節，則痤疽的爪角害的。好用他的私智而且棄道理，則網羅的爪角害的。兕虎有域，而且萬害有原，避他的域，塞他的原，則免於諸害矣。凡兵革的人或事物，所以備害啊。重生的人或事物雖入軍無忿爭的心，無忿爭的心則無所用救害的備。此絕不是獨謂野處的軍啊，聖人的遊世啊無害人的心，無害人的心則必無人害，無人害則不備人，因此韓絕不是子評論說道：陸行不遇兕虎。入山不恃備以救害，因此韓絕不是子評論說道：入軍不備甲兵。遠諸害，因此韓絕不是子評論說道：兕無所投他的角，虎無所錯他的爪，兵無所容他的刃。不設備而且必無害，天地的道理啊。體天地的道，因此韓絕不是子評論說道：無死地焉。動無死地，而且謂的善攝生矣。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 26 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人始於生而卒於死」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人始於生而卒於死。始之謂出，卒之謂入，故曰：「出生入……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-27","chapterId":"han-fei-zi_ch-22","order":27,"canonicalText":"愛子者慈於子，重生者慈於身，貴功者慈於事。慈母之於弱子也，務致其福，務致其福則事除其禍，事除其禍則思慮熟，思慮熟則得事理，得事理則必成功，必成功則其行之也不疑，不疑之謂勇。聖人之於萬事也，盡如慈母之為弱子慮也，故見必行之道，見必行之道則明，其從事亦不疑，不疑之謂勇。不疑生於慈，故曰：「慈故能勇。」","sentenceIds":["han-fei-zi_ch-22_p-27_s-1","han-fei-zi_ch-22_p-27_s-2","han-fei-zi_ch-22_p-27_s-3","han-fei-zi_ch-22_p-27_s-4","han-fei-zi_ch-22_p-27_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"愛子的人或事物慈於子，重生的人或事物慈於身，貴功的人或事物慈於事。慈母的於弱子啊，務致他的福，務致他的福則事除他的禍，事除他的禍則思慮熟，思慮熟則得事理，得事理則必成功，必成功則他的行的啊不疑，不疑的謂勇。聖人的於萬事啊，盡如慈母的為弱子慮啊，所以見必行的道，見必行的道則明，他的從事亦不疑，不疑的謂勇。不疑生於慈，因此韓絕不是子評論說道：慈所以能勇。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 27 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「愛子者慈於子，重生者慈於身，貴功者慈於事」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「愛子者慈於子，重生者慈於身，貴功者慈於事。慈母之於弱……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-28","chapterId":"han-fei-zi_ch-22","order":28,"canonicalText":"周公曰：「冬日之閉凍也不固，則春夏之長草木也不茂。」天地不能常侈常費，而況於人乎？故萬物必有盛衰，萬事必有弛張，國家必有文武，官治必有賞罰。是以智士儉用其財則家富，聖人愛寶其神則精盛，人君重戰其卒則民眾。民眾則國廣，是以舉之曰：「儉故能廣。」","sentenceIds":["han-fei-zi_ch-22_p-28_s-1","han-fei-zi_ch-22_p-28_s-2","han-fei-zi_ch-22_p-28_s-3","han-fei-zi_ch-22_p-28_s-4","han-fei-zi_ch-22_p-28_s-5","han-fei-zi_ch-22_p-28_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周公說道：冬日的閉凍啊不固，則春夏的長草木啊不茂。天地不能常侈常費，而且況於人乎？所以萬物必有盛衰，萬事必有弛張，國家必有文武，官治必有賞賜恩惠刑罰制裁。是以智士儉用他的財則家富，聖人愛寶他的神則精盛，人君主統治者重戰他的卒則民眾。民眾則國廣，是以舉的說道：儉所以能廣。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 28 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「周公曰：「冬日之閉凍也不固，則春夏之長草木也不茂」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「周公曰：「冬日之閉凍也不固，則春夏之長草木也不茂。」……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-29","chapterId":"han-fei-zi_ch-22","order":29,"canonicalText":"凡物之有形者易裁也，易割也。何以論之？有形則有短長，有短長則有小大，有小大則有方圓，有方圓則有堅脆，有堅脆則有輕重，有輕重則有白黑。短長、大小、方圓、堅脆、輕重、白黑之謂理。理定而物易割也。故議於大庭而後言則立，權議之士知之矣。故欲成方圓而隨其規矩，則萬事之功形矣。而萬物莫不有規矩。議言之士，計會規矩也。聖人盡隨於萬物之規矩，故曰：「不敢為天下先。」不敢為天下先則事無不事，功無不功，而議必蓋世，欲無處大官，其可得乎？處大官之謂為成事長，是以故曰：「不敢為天下先，故能為成事長。」","sentenceIds":["han-fei-zi_ch-22_p-29_s-1","han-fei-zi_ch-22_p-29_s-2","han-fei-zi_ch-22_p-29_s-3","han-fei-zi_ch-22_p-29_s-4","han-fei-zi_ch-22_p-29_s-5","han-fei-zi_ch-22_p-29_s-6","han-fei-zi_ch-22_p-29_s-7","han-fei-zi_ch-22_p-29_s-8","han-fei-zi_ch-22_p-29_s-9","han-fei-zi_ch-22_p-29_s-10","han-fei-zi_ch-22_p-29_s-11","han-fei-zi_ch-22_p-29_s-12","han-fei-zi_ch-22_p-29_s-13"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡物的有形的人或事物易裁啊，易割啊。何以論的？有形則有短長，有短長則有小大，有小大則有方圓，有方圓則有堅脆，有堅脆則有輕重，有輕重則有白黑。短長、大小、方圓、堅脆、輕重、白黑的謂理。理定而且物易割啊。所以議於大庭而且後言則立，權議的士知的矣。所以欲成方圓而且隨他的規矩，則萬事的功形矣。而且萬物莫不有規矩。議言的士，計會規矩啊。聖人盡隨於萬物的規矩，因此韓絕不是子評論說道：不敢為天下先。不敢為天下先則事無不事，功無不功，而且議必蓋世，欲無處大官，他的可得乎？處大官的謂為成事長，是以因此韓絕不是子評論說道：不敢為天下先，所以能為成事長。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 29 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「凡物之有形者易裁也，易割也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「凡物之有形者易裁也，易割也。何以論之？有形則有短長，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-30","chapterId":"han-fei-zi_ch-22","order":30,"canonicalText":"慈於子者不敢絕衣食，慈於身者不敢離法度，慈於方圓者不敢舍規矩。故臨兵而慈於士吏則戰勝敵，慈於器械則城堅固。故曰：「慈於戰則勝，以守則固。」夫能自全也而盡隨於萬物之理者，必且有天生。天生也者，生心也。故天下之道盡之生也，若以慈衛之也。事必萬全，而舉無不當，則謂之寶矣。故曰：「吾有三寶，持而寶之。」","sentenceIds":["han-fei-zi_ch-22_p-30_s-1","han-fei-zi_ch-22_p-30_s-2","han-fei-zi_ch-22_p-30_s-3","han-fei-zi_ch-22_p-30_s-4","han-fei-zi_ch-22_p-30_s-5","han-fei-zi_ch-22_p-30_s-6","han-fei-zi_ch-22_p-30_s-7","han-fei-zi_ch-22_p-30_s-8","han-fei-zi_ch-22_p-30_s-9"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"慈於子的人或事物不敢絕衣食，慈於身的人或事物不敢離國家法度法規度，慈於方圓的人或事物不敢舍規矩。所以臨兵而且慈於士吏則戰勝敵，慈於器械則城堅固。因此韓絕不是子評論說道：慈於戰則勝，以守則固。夫能自全啊而且盡隨於萬物的理的人或事物，必且有天生。天生啊的人或事物，生心啊。所以天下的道盡的生啊，若以慈衛的啊。事必萬全，而且舉無不當，則謂的寶矣。因此韓絕不是子評論說道：吾有三寶，持而且寶的。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 30 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「慈於子者不敢絕衣食，慈於身者不敢離法度，慈於方圓者不敢舍規矩」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「慈於子者不敢絕衣食，慈於身者不敢離法度，慈於方圓者不……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-31","chapterId":"han-fei-zi_ch-22","order":31,"canonicalText":"書之所謂大道也者，端道也。所謂貌施也者，邪道也。所謂徑大也者，佳麗也。佳麗也者，邪道之分也。朝甚除也者，獄訟繁也。獄訟繁則田荒，田荒則府倉虛，府倉虛則國貧，國貧而民俗淫侈，民俗淫侈則衣食之業絕，衣食之業絕則民不得無飾巧詐，飾巧詐則知採文，知採文之謂服文采。獄訟繁、倉廩虛、而有以淫侈為俗，則國之傷也若以利劍刺之。故曰：「帶利劍。」諸夫飾智故以至於傷國者，其私家必富，私家必富，故曰：「資貨有餘。」國有若是者，則愚民不得無術而效之，效之則小盜生。由是觀之，大姦作則小盜隨，大姦唱則小盜和。竽也者，五聲之長者也，故竽先則鍾瑟皆隨，竽唱則諸樂皆和。今大姦作則俗之民唱，俗之民唱則小盜必和，故服文采，帶利劍，厭飲食，而貨資有餘者，是之謂盜竽矣。","sentenceIds":["han-fei-zi_ch-22_p-31_s-1","han-fei-zi_ch-22_p-31_s-2","han-fei-zi_ch-22_p-31_s-3","han-fei-zi_ch-22_p-31_s-4","han-fei-zi_ch-22_p-31_s-5","han-fei-zi_ch-22_p-31_s-6","han-fei-zi_ch-22_p-31_s-7","han-fei-zi_ch-22_p-31_s-8","han-fei-zi_ch-22_p-31_s-9","han-fei-zi_ch-22_p-31_s-10","han-fei-zi_ch-22_p-31_s-11","han-fei-zi_ch-22_p-31_s-12","han-fei-zi_ch-22_p-31_s-13"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"書的所謂大道啊的人或事物，端道啊。所謂貌施啊的人或事物，邪道啊。所謂徑大啊的人或事物，佳麗啊。佳麗啊的人或事物，邪道的分啊。朝甚除啊的人或事物，獄訟繁啊。獄訟繁則田荒，田荒則府倉虛，府倉虛則國貧，國貧而且民俗淫侈，民俗淫侈則衣食的業絕，衣食的業絕則民不得無飾巧詐，飾巧詐則知採文，知採文的謂服文采。獄訟繁、倉廩虛、而且有以淫侈為俗，則國的傷啊若以利劍刺的。因此韓絕不是子評論說道：帶利劍。諸夫飾智所以以至於傷國的人或事物，他的私家必富，私家必富，因此韓絕不是子評論說道：資貨有餘。國有若是的人或事物，則愚民不得無御臣心術權謀而且效的，效的則小盜生。由是觀的，大姦作則小盜隨，大姦唱則小盜和。竽啊的人或事物，五聲的長的人或事物啊，所以竽先則鍾瑟皆隨，竽唱則諸樂皆和。今大姦作則俗的民唱，俗的民唱則小盜必和，所以服文采，帶利劍，厭飲食，而且貨資有餘的人或事物，是的謂盜竽矣。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 31 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「書之所謂大道也者，端道也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「書之所謂大道也者，端道也。所謂貌施也者，邪道也。所謂……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-22_p-32","chapterId":"han-fei-zi_ch-22","order":32,"canonicalText":"人無愚智，莫不有趨舍。恬淡平安，莫不知禍福之所由來。得於好惡，怵於淫物，而後變亂。所以然者，引於外物，亂於玩好也。恬淡有趨舍之義，平安知禍福之計。而今也玩好變之，外物引之，引之而往，故曰：「拔。」至聖人不然，一建其趨舍，雖見所好之物不能引，不能引之謂不拔。一於其情，雖有可欲之類，神不為動，神不為動之謂不脫。為人子孫者體此道，以守宗廟不滅之謂祭祀不絕。身以積精為德，家以資財為德，鄉國天下皆以民為德。今治身而外物不能亂其精神，故曰：「脩之身，其德乃真。」真者，慎之固也。治家，無用之物不能動其計則資有餘，故曰：「脩之家，其德有餘。」治鄉者行此節，則家之有餘者益眾，故曰：「脩之鄉，其德乃長。」治邦者行此節，則鄉之有德者益眾，故曰：「脩之邦，其德乃豐。」蒞天下者行此節，則民之生莫不受其澤，故曰：「脩之天下，其德乃普。」脩身者以此別君子小人，治鄉治邦蒞天下者各以此科適觀息耗則萬不失一，故曰：「以身觀身，以家觀家，以鄉觀鄉，以邦觀邦，以天下觀天下，吾奚以知天下之然也？以此。」","sentenceIds":["han-fei-zi_ch-22_p-32_s-1","han-fei-zi_ch-22_p-32_s-2","han-fei-zi_ch-22_p-32_s-3","han-fei-zi_ch-22_p-32_s-4","han-fei-zi_ch-22_p-32_s-5","han-fei-zi_ch-22_p-32_s-6","han-fei-zi_ch-22_p-32_s-7","han-fei-zi_ch-22_p-32_s-8","han-fei-zi_ch-22_p-32_s-9","han-fei-zi_ch-22_p-32_s-10","han-fei-zi_ch-22_p-32_s-11","han-fei-zi_ch-22_p-32_s-12","han-fei-zi_ch-22_p-32_s-13","han-fei-zi_ch-22_p-32_s-14","han-fei-zi_ch-22_p-32_s-15","han-fei-zi_ch-22_p-32_s-16","han-fei-zi_ch-22_p-32_s-17","han-fei-zi_ch-22_p-32_s-18","han-fei-zi_ch-22_p-32_s-19"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人無愚智，莫不有趨舍。恬淡平安，莫不知禍福的所由來。得於好惡，怵於淫物，而且後變亂。所以然的人或事物，引於外物，亂於玩好啊。恬淡有趨舍的義，平安知禍福的計。而且今啊玩好變的，外物引的，引的而且往，因此韓絕不是子評論說道：拔。至聖人不然，一建他的趨舍，雖見所好的物不能引，不能引的謂不拔。一於他的情，雖有可欲的類，神不為動，神不為動的謂不脫。為人子孫的人或事物體此道，以守宗廟不滅的謂祭祀不絕。身以積精為德，家以資財為德，鄉國天下皆以民為德。今治身而且外物不能亂他的精神，因此韓絕不是子評論說道：脩的身，他的德乃真。真的人或事物，慎的固啊。治家，無用的物不能動他的計則資有餘，因此韓絕不是子評論說道：脩的家，他的德有餘。治鄉的人或事物行此節，則家的有餘的人或事物益眾，因此韓絕不是子評論說道：脩的鄉，他的德乃長。治邦的人或事物行此節，則鄉的有德的人或事物益眾，因此韓絕不是子評論說道：脩的邦，他的德乃豐。蒞天下的人或事物行此節，則民的生莫不受他的澤，因此韓絕不是子評論說道：脩的天下，他的德乃普。脩身的人或事物以此別君主統治者子小人，治鄉治邦蒞天下的人或事物各以此科適觀息耗則萬不失一，因此韓絕不是子評論說道：以身觀身，以家觀家，以鄉觀鄉，以邦觀邦，以天下觀天下，吾奚以知天下的然啊？以此。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈解老〉（第 32 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「人無愚智，莫不有趨舍」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「人無愚智，莫不有趨舍。恬淡平安，莫不知禍福之所由來。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"han-fei-zi_ch-22_p-1_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":1,"canonicalText":"德者，內也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":2,"canonicalText":"得者，外也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":3,"canonicalText":"上德不德，言其神不淫於外也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":4,"canonicalText":"神不淫於外則身全，身全之謂德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":5,"canonicalText":"德者，得身也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":6,"canonicalText":"凡德者，以無為集，以無欲成，以不思安，以不用固。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":7,"canonicalText":"為之慾之，則德無舍，德無舍則不全。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":8,"canonicalText":"用之思之則不固，不固則無功，無功則生於德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":9,"canonicalText":"德則無德，不德則在有德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":10,"canonicalText":"故曰：「上德不德，是以有德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-1_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-1","order":11,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-2_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-2","order":1,"canonicalText":"所以貴無為無思為虛者，謂其意無所制也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-2_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-2","order":2,"canonicalText":"夫無術者，故以無為無思為虛也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-2_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-2","order":3,"canonicalText":"夫故以無為無思為虛者，其意常不忘虛，是制於為虛也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-2_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-2","order":4,"canonicalText":"虛者，謂其意無所制也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-2_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-2","order":5,"canonicalText":"今制於為虛，是不虛也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-2_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-2","order":6,"canonicalText":"虛者之無為也，不以無為為有常，不以無為為有常則虛，虛則德盛，德盛之謂上德，故曰：「上德無為而無不為也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-2_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-2","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-3_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-3","order":1,"canonicalText":"仁者，謂其中心欣然愛人也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-3_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-3","order":2,"canonicalText":"其喜人之有福，而惡人之有禍也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-3_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-3","order":3,"canonicalText":"生心之所不能已也，非求其報也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-3_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-3","order":4,"canonicalText":"故曰：「上仁為之而無以為也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-3_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-3","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-4_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-4","order":1,"canonicalText":"義者，君臣上下之事，父子貴賤之差也，知交朋友之接也，親疏內外之分也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-4_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-4","order":2,"canonicalText":"臣事君宜，下懷上宜，子事父宜，賤敬貴宜，知交友朋之相助也宜，親者內而疏者外宜。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-4_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-4","order":3,"canonicalText":"義者，謂其宜也，宜而為之，故曰：「上義為之而有以為也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-4_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-4","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":1,"canonicalText":"禮者，所以貌情也，羣義之文章也，君臣父子之交也，貴賤賢不肖之所以別也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":2,"canonicalText":"中心懷而不諭，故疾趨卑拜而明之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":3,"canonicalText":"實心愛而不知，故好言繁辭以信之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":4,"canonicalText":"禮者，外節之所以諭內也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":5,"canonicalText":"故曰：「禮以貌情也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":6,"canonicalText":"」凡人之為外物動也，不知其為身之禮也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":7,"canonicalText":"眾人之為禮也，以尊他人也，故時勸時衰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":8,"canonicalText":"君子之為禮，以為其身，以為其身，故神之為上禮，上禮神而眾人貳，故不能相應，不能相應，故曰：「上禮為之而莫之應。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":9,"canonicalText":"」眾人雖貳，聖人之復恭敬盡手足之禮也不衰，故曰：「攘臂而仍之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":10,"canonicalText":"」道有積而德有功，德者道之功。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":11,"canonicalText":"功有實而實有光，仁者德之光。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":12,"canonicalText":"光有澤而澤有事，義者仁之事也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":13,"canonicalText":"事有禮而禮有文，禮者義之文也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":14,"canonicalText":"故曰：「失道而後失德，失德而後失仁，失仁而後失義，失義而後失禮。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-5_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-5","order":15,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":1,"canonicalText":"禮為情貌者也，文為質飾者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":2,"canonicalText":"夫君子取情而去貌，好質而惡飾。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":3,"canonicalText":"夫恃貌而論情者，其情惡也；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":4,"canonicalText":"須飾而論質者，其質衰也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":5,"canonicalText":"何以論之？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":6,"canonicalText":"和氏之璧，不飾以五采，隋侯之珠，不飾以銀黃，其質至美，物不足以飾之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":7,"canonicalText":"夫物之待飾而後行者，其質不美也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":8,"canonicalText":"是以父子之間，其禮樸而不明，故曰：「禮薄也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":9,"canonicalText":"」凡物不並盛，陰陽是也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":10,"canonicalText":"理相奪予，威德是也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":11,"canonicalText":"實厚者貌薄，父子之禮是也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":12,"canonicalText":"由是觀之，禮繁者實心衰也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":13,"canonicalText":"然則為禮者，事通人之樸心者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":14,"canonicalText":"眾人之為禮也，人應則輕歡，不應則責怨。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":15,"canonicalText":"今為禮者事通人之樸心，而資之以相責之分，能毋爭乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-16","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":16,"canonicalText":"有爭則亂，故曰：「禮者，忠信之薄也，而亂之首乎。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-6_s-17","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-6","order":17,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":1,"canonicalText":"先物行先理動之謂前識，前識者，無緣而忘意度也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":2,"canonicalText":"何以論之？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":3,"canonicalText":"詹何坐，弟子侍，有牛鳴於門外，弟子曰：「是黑牛也而白題。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":4,"canonicalText":"」詹何曰：「然，是黑牛也，而白在其角。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":5,"canonicalText":"」使人視之，果黑牛而以布裹其角。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":6,"canonicalText":"以詹子之術，嬰眾人之心，華焉殆矣，故曰「道之華也」。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":7,"canonicalText":"嘗試釋詹子之察，而使五尺之愚童子視之，亦知其黑牛而以布裹其角也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":8,"canonicalText":"故以詹子之察，苦心傷神，而後與五尺之愚童子同功，是以曰「愚之首也」。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":9,"canonicalText":"故曰：「前識者道之華也，而愚之首也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-7_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-7","order":10,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-8_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-8","order":1,"canonicalText":"所謂大丈夫者，謂其智之大也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-8_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-8","order":2,"canonicalText":"所謂處其厚不處其薄者，行情實而去禮貌也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-8_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-8","order":3,"canonicalText":"所謂處其實不處其華者，必緣理不徑絕也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-8_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-8","order":4,"canonicalText":"所謂去彼取此者，去貌徑絕而取緣理好情實也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-8_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-8","order":5,"canonicalText":"故曰：「去彼取此。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-8_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-8","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-9_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-9","order":1,"canonicalText":"人有禍則心畏恐，心畏恐則行端直，行端直則思慮熟，思慮熟則得事理，行端直則無禍害，無禍害則盡天年，得事理則必成功，盡天年則全而壽，必成功則富與貴，全壽富貴之謂福。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-9_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-9","order":2,"canonicalText":"而福本於有禍，故曰：「禍兮福之所倚。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-9_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-9","order":3,"canonicalText":"」以成其功也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-10_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-10","order":1,"canonicalText":"人有福則富貴至，富貴至則衣食美，衣食美則驕心生，驕心生則行邪僻而動棄理，行邪僻則身死夭，動棄理則無成功。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-10_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-10","order":2,"canonicalText":"夫內有死夭之難，而外無成功之名者，大禍也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-10_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-10","order":3,"canonicalText":"而禍本生於有福，故曰：「福兮禍之所伏」。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":1,"canonicalText":"夫緣道理以從事者無不能成。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":2,"canonicalText":"無不能成者，大能成天子之勢尊，而小易得卿相將軍之賞祿。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":3,"canonicalText":"夫棄道理而忘舉動者，雖上有天子諸侯之勢尊，而下有猗頓、陶朱、卜祝之富，猶失其民人而亡其財資也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":4,"canonicalText":"眾人之輕棄道理而易忘舉動者，不知其禍福之深大而道闊遠若是也，故諭人曰：「熟知其極。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":5,"canonicalText":"」人莫不欲富貴全壽，而未有能免於貧賤死夭之禍也，心欲富貴全壽，而今貧賤死夭，是不能至於其所欲至也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":6,"canonicalText":"凡失其所欲之路而妄行者之謂迷，迷則不能至於其所欲至矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":7,"canonicalText":"今眾人之不能至於其所欲至，故曰「迷」。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":8,"canonicalText":"眾人之所不能至於其所欲至也，自天地之剖判以至於今，故曰：「人之迷也，其日故以久矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-11_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-11","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":1,"canonicalText":"所謂方者，內外相應也，言行相稱也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":2,"canonicalText":"所謂廉者，必生死之命也，輕恬資財也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":3,"canonicalText":"所謂直者，義必公正，公心不偏黨也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":4,"canonicalText":"所謂光者，官爵尊貴，衣裘壯麗也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":5,"canonicalText":"今有道之士，雖中外信順，不以誹謗窮墮；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":6,"canonicalText":"雖死節輕財，不以侮罷羞貪；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":7,"canonicalText":"雖義端不黨，不以去邪罪私；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":8,"canonicalText":"雖勢尊衣美，不以誇賤欺貧。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":9,"canonicalText":"其故何也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":10,"canonicalText":"使失路者而肯聽習問知，即不成迷也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":11,"canonicalText":"今眾人之所以欲成功而反為敗者，生於不知道理而不肯問知而聽能。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":12,"canonicalText":"眾人不肯問知聽能，而聖人強以其禍敗適之，則怨。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":13,"canonicalText":"眾人多而聖人寡，寡之不勝眾，數也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":14,"canonicalText":"今舉動而與天下之為讎，非全身長生之道也，是以行軌節而舉之也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":15,"canonicalText":"故曰：「方而不割，廉而不劌，直而不肆，光而不耀。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-12_s-16","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-12","order":16,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":1,"canonicalText":"聰明睿智天也，動靜思慮人也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":2,"canonicalText":"人也者，乘於天明以視，寄於天聰以聽，託於天智以思慮。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":3,"canonicalText":"故視強則目不明，聽甚則耳不聰，思慮過度則智識亂。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":4,"canonicalText":"目不明則不能決黑白之分，耳不聰則不能別清濁之聲，智識亂則不能審得失之地。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":5,"canonicalText":"目不能決黑白之色則謂之盲，耳不能別清濁之聲則謂之聾，心不能審得失之地則謂之狂。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":6,"canonicalText":"盲則不能避晝日之險，聾則不能知雷霆之害，狂則不能免人間法令之禍。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":7,"canonicalText":"書之所謂治人者，適動靜之節，省思慮之費也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":8,"canonicalText":"所謂事天者，不極聰明之力，不盡智識之任。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":9,"canonicalText":"苟極盡則費神多，費神多則盲聾悖狂之禍至，是以嗇之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":10,"canonicalText":"嗇之者，愛其精神，嗇其智識也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":11,"canonicalText":"故曰：「治人事天莫如嗇。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-13_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-13","order":12,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":1,"canonicalText":"眾人之用神也躁，躁則多費，多費之謂侈。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":2,"canonicalText":"聖人之用神也靜，靜則少費，少費之謂嗇。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":3,"canonicalText":"嗇之謂術也生於道理。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":4,"canonicalText":"夫能嗇也，是從於道而服於理者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":5,"canonicalText":"眾人離於患，陷於禍，猶未知退，而不服從道理。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":6,"canonicalText":"聖人雖未見禍患之形，虛無服從於道理，以稱蚤服。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":7,"canonicalText":"故曰：「夫謂嗇，是以蚤服。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-14_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-14","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":1,"canonicalText":"知治人者其思慮靜，知事天者其孔竅虛。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":2,"canonicalText":"思慮靜，故德不去。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":3,"canonicalText":"孔竅虛，則和氣日入。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":4,"canonicalText":"故曰：「重積德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":5,"canonicalText":"」夫能令故德不去，新和氣日至者，蚤服者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":6,"canonicalText":"故曰：「蚤服是謂重積德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":7,"canonicalText":"」積德而後神靜，神靜而後和多，和多而後計得，計得而後能御萬物，能御萬物則戰易勝敵，戰易勝敵而論必蓋世，論必蓋世，故曰「無不克」。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":8,"canonicalText":"無不克本於重積德，故曰「重積德則無不克」。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":9,"canonicalText":"戰易勝敵則兼有天下，論必蓋世則民人從。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":10,"canonicalText":"進兼天下而退從民人，其術遠，則眾人莫見其端末。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":11,"canonicalText":"莫見其端末，是以莫知其極，故曰：「無不克則莫知其極。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-15_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-15","order":12,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-16_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-16","order":1,"canonicalText":"凡有國而後亡之，有身而後殃之，不可謂能有其國能保其身。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-16_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-16","order":2,"canonicalText":"夫能有其國、必能安其社稷，能保其身、必能終其天年，而後可謂能有其國、能保其身矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-16_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-16","order":3,"canonicalText":"夫能有其國、保其身者必且體道，體道則其智深，其智深則其會遠，其會遠眾人莫能見其所極。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-16_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-16","order":4,"canonicalText":"唯夫能令人不見其事極，不見事極者為保其身、有其國，故曰：「莫知其極；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-16_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-16","order":5,"canonicalText":"莫知其極，則可以有國。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-16_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-16","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":1,"canonicalText":"所謂有國之母，母者，道也，道也者生於所以有國之術，所以有國之術，故謂之有國之母。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":2,"canonicalText":"夫道以與世周旋者，其建生也長，持祿也久，故曰：「有國之母，可以長久。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":3,"canonicalText":"」樹木有曼根，有直根。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":4,"canonicalText":"根者，書之所謂柢也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":5,"canonicalText":"柢也者，木之所以建生也；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":6,"canonicalText":"曼根者，木之所以持生也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":7,"canonicalText":"德也者，人之所以建生也；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":8,"canonicalText":"祿也者，人之所以持生也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":9,"canonicalText":"今建於理者其持祿也久，故曰：「深其根。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":10,"canonicalText":"」體其道者，其生日長，故曰：「固其柢。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":11,"canonicalText":"」柢固則生長，根深則視久，故曰：「深其根，固其柢，長生久視之道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-17_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-17","order":12,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-18_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-18","order":1,"canonicalText":"工人數變業則失其功，作者數搖徙則亡其功。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-18_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-18","order":2,"canonicalText":"一人之作，日亡半日，十日則亡五人之功矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-18_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-18","order":3,"canonicalText":"萬人之作，日亡半日，十日則亡五萬人之功矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-18_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-18","order":4,"canonicalText":"然則數變業者，其人彌眾，其虧彌大矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-18_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-18","order":5,"canonicalText":"凡法令更則利害易，利害易則民務變，務變之謂變業。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-18_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-18","order":6,"canonicalText":"故以理觀之，事大眾而數搖之則少成功，藏大器而數徙之則多敗傷，烹小鮮而數撓之則賊其澤，治大國而數變法則民苦之，是以有道之君貴靜，不重變法，故曰：「治大國者若烹小鮮。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-18_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-18","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":1,"canonicalText":"人處疾則貴醫，有禍則畏鬼。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":2,"canonicalText":"聖人在上則民少欲，民少欲則血氣治，而舉動理則少禍害。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":3,"canonicalText":"夫內無痤疽癉痔之害，而外無刑罰法誅之禍者，其輕恬鬼也甚，故曰：「以道蒞天下，其鬼不神。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":4,"canonicalText":"」治世之民不與鬼神相害也，故曰：「非其鬼不神也，其神不傷人也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":5,"canonicalText":"」鬼崇也疾人之謂鬼傷人，人逐除之之謂人傷鬼也；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":6,"canonicalText":"民犯法令之謂民傷上，上刑戮民之謂上傷民；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":7,"canonicalText":"民不犯法則上亦不行刑，上不行刑之謂上不傷人；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":8,"canonicalText":"故曰：「聖人亦不傷民。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":9,"canonicalText":"」上不與民相害，而人不與鬼相傷，故曰：「兩不相傷。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":10,"canonicalText":"」民不敢犯法，則上內不用刑罰，而外不事利其產業，上內不用刑罰、而外不事利其產業則民蕃息，民蕃息而畜積盛，民蕃息而畜積盛之謂有德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":11,"canonicalText":"凡所謂崇者，魂魄去而精神亂，精神亂則無德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":12,"canonicalText":"鬼不崇人則魂魄不去，魂魄不去而精神不亂，精神不亂之謂有德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":13,"canonicalText":"上盛畜積，而鬼不亂其精神，則德盡在於民矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":14,"canonicalText":"故曰：「兩不相傷，則德交歸焉。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-19_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-19","order":15,"canonicalText":"」言其德上下交盛而俱歸於民也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":1,"canonicalText":"有道之君，外無怨讎於鄰敵，而內有德澤於人民。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":2,"canonicalText":"夫外無怨讎於鄰敵者，其遇諸侯也外有禮義。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":3,"canonicalText":"內有德澤於人民者，其治人事也務本。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":4,"canonicalText":"遇諸侯有禮義則役希起，治民事務本則淫奢止。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":5,"canonicalText":"凡馬之所以大用者，外供甲兵，而內給淫奢也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":6,"canonicalText":"今有道之君，外希用甲兵，而內禁淫奢。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":7,"canonicalText":"上不事馬於戰鬥逐北，而民不以馬遠淫通物，所積力唯田疇，積力於田疇必且糞灌，故曰：「天下有道，卻走馬以糞也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-20_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-20","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":1,"canonicalText":"人君者無道，則內暴虐其民，而外侵欺其鄰國。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":2,"canonicalText":"內暴虐則民產絕，外侵欺則兵數起。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":3,"canonicalText":"民產絕則畜生少，兵數起則士卒盡。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":4,"canonicalText":"畜生少則戎馬乏，士卒盡則軍危殆。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":5,"canonicalText":"戎馬乏則將馬出，軍危殆則近臣役。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":6,"canonicalText":"馬者，軍之大用；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":7,"canonicalText":"郊者，言其近也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":8,"canonicalText":"今所以給軍之具於將馬近臣，故曰：「天下無道，戎馬生於郊矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-21_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-21","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":1,"canonicalText":"人有欲則計會亂，計會亂而有欲甚，有欲甚則邪心勝，邪心勝則事經絕，事經絕則禍難生。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":2,"canonicalText":"由是觀之，禍難生於邪心，邪心誘於可欲。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":3,"canonicalText":"可欲之類，進則教良民為姦，退則令善人有禍。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":4,"canonicalText":"姦起則上侵弱君，禍至則民人多傷。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":5,"canonicalText":"然則可欲之類，上侵弱君而下傷人民。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":6,"canonicalText":"夫上侵弱君而下傷人民者，大罪也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":7,"canonicalText":"故曰：「禍莫大於可欲。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":8,"canonicalText":"」是以聖人不引五色，不淫於聲樂，明君賤玩好而去淫麗。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":9,"canonicalText":"人無毛羽，不衣則不犯寒。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":10,"canonicalText":"上不屬天，而下不著地，以腸胃為根本，不食則不能活。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":11,"canonicalText":"是以不免於欲利之心，欲利之心不除，其身之憂也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":12,"canonicalText":"故聖人衣足以犯寒，食足以充虛，則不憂矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":13,"canonicalText":"眾人則不然，大為諸侯，小餘千金之資，其欲得之憂不除也，胥靡有免，死罪時活，今不知足者之憂，終身不解，故曰：「禍莫大於不知足。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":14,"canonicalText":"」故欲利甚於憂，憂則疾生，疾生而智慧衰，智慧衰則失度量，失度量則妄舉動，妄舉動則禍害至，禍害至而疾嬰內，疾嬰內則痛禍薄外，痛禍薄外則苦痛雜於腸胃之間，苦痛雜於腸胃之間則傷人也憯，憯則退而自咎，退而自咎也生於欲利，故曰：「咎莫憯於欲利。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-22_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-22","order":15,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":1,"canonicalText":"道者，萬物之所然也，萬理之所稽也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":2,"canonicalText":"理者，成物之文也；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":3,"canonicalText":"道者，萬物之所以成也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":4,"canonicalText":"故曰：「道，理之者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":5,"canonicalText":"」物有理不可以相薄，物有理不可以相薄故理之為物之制。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":6,"canonicalText":"萬物各異理，萬物各異理而道盡。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":7,"canonicalText":"稽萬物之理，故不得不化；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":8,"canonicalText":"不得不化，故無常操；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":9,"canonicalText":"無常操，是以死生氣稟焉，萬智斟酌焉，萬事廢興焉。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":10,"canonicalText":"天得之以高，地得之以藏，維鬥得之以成其威，日月得之以恆其光，五常得之以常其位，列星得之以端其行，四時得之以御其變氣，軒轅得之以擅四方，赤松得之與天地統，聖人得之以成文章。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":11,"canonicalText":"道與堯、舜俱智，與接輿俱狂，與桀、紂俱滅，與湯、武俱昌。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":12,"canonicalText":"以為近乎，遊於四極；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":13,"canonicalText":"以為遠乎，常在吾側；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":14,"canonicalText":"以為暗乎，其光昭昭；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":15,"canonicalText":"以為明乎，其物冥冥；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-16","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":16,"canonicalText":"而功成天地，和化雷霆，宇內之物，恃之以成。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-17","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":17,"canonicalText":"凡道之情，不制不形，柔弱隨時，與理相應。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-18","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":18,"canonicalText":"萬物得之以死，得之以生；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-19","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":19,"canonicalText":"萬事得之以敗，得之以成。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-20","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":20,"canonicalText":"道譬諸若水，溺者多飲之即死，渴者適飲之即生。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-21","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":21,"canonicalText":"譬之若劍戟，愚人以行忿則禍生，聖人以誅暴則福成。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-23_s-22","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-23","order":22,"canonicalText":"故得之以死，得之以生，得之以敗，得之以成。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-24_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-24","order":1,"canonicalText":"人希見生象也，而得死象之骨，案其圖以想其生也，故諸人之所以意想者皆謂之象也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-24_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-24","order":2,"canonicalText":"今道雖不可得聞見，聖人執其見功以處見其形，故曰：「無狀之狀，無物之象。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-24_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-24","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":1,"canonicalText":"凡理者，方圓、短長、麤靡、堅脆之分也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":2,"canonicalText":"故理定而後可得道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":3,"canonicalText":"故定理有存亡，有死生，有盛衰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":4,"canonicalText":"夫物之一存一亡，乍死乍生，初盛而後衰者，不可謂常。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":5,"canonicalText":"唯夫與天地之剖判也具生，至天地之消散也不死不衰者謂常。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":6,"canonicalText":"而常者，無攸易，無定理，無定理非在於常所，是以不可道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":7,"canonicalText":"聖人觀其玄虛，用其周行，強字之曰道，然而可論，故曰：「道之可道，非常道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-25_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-25","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":1,"canonicalText":"人始於生而卒於死。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":2,"canonicalText":"始之謂出，卒之謂入，故曰：「出生入死。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":3,"canonicalText":"」人之身三百六十節，四肢，九竅，其大具也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":4,"canonicalText":"四肢與九竅十有三者，十有三者之動靜盡屬於生焉。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":5,"canonicalText":"屬之謂徒也，故曰：「生之徒也十有三者。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":6,"canonicalText":"」至死也十有三具者皆還而屬之於死，死之徒亦有十三，故曰：「生之徒，十有三；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":7,"canonicalText":"死之徒，十有三。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":8,"canonicalText":"」凡民之生生而生者固動，動盡則損也，而動不止，是損而不止也，損而不止則生盡，生盡之謂死，則十有三具者皆為死死地也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":9,"canonicalText":"故曰：「民之生，生而動，動皆之死地，之十有三。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":10,"canonicalText":"」是以聖人愛精神而貴處靜，此甚大於兕虎之害。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":11,"canonicalText":"夫兕虎有域，動靜有時，避其域，省其時，則免其兕虎之害矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":12,"canonicalText":"民獨知兕虎之有爪角也，而莫知萬物之盡有爪角也，不免於萬物之害。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":13,"canonicalText":"何以論之？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":14,"canonicalText":"時雨降集，曠野閒靜，而以昏晨犯山川，則風露之爪角害之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":15,"canonicalText":"事上不忠，輕犯禁令，則刑法之爪角害之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-16","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":16,"canonicalText":"處鄉不節，憎愛無度，則爭鬥之爪角害之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-17","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":17,"canonicalText":"嗜慾無限，動靜不節，則痤疽之爪角害之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-18","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":18,"canonicalText":"好用其私智而棄道理，則網羅之爪角害之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-19","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":19,"canonicalText":"兕虎有域，而萬害有原，避其域，塞其原，則免於諸害矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-20","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":20,"canonicalText":"凡兵革者，所以備害也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-21","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":21,"canonicalText":"重生者雖入軍無忿爭之心，無忿爭之心則無所用救害之備。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-22","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":22,"canonicalText":"此非獨謂野處之軍也，聖人之遊世也無害人之心，無害人之心則必無人害，無人害則不備人，故曰：「陸行不遇兕虎。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-23","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":23,"canonicalText":"」入山不恃備以救害，故曰：「入軍不備甲兵。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-24","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":24,"canonicalText":"」遠諸害，故曰：「兕無所投其角，虎無所錯其爪，兵無所容其刃。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-25","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":25,"canonicalText":"」不設備而必無害，天地之道理也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-26","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":26,"canonicalText":"體天地之道，故曰：「無死地焉。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-26_s-27","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-26","order":27,"canonicalText":"」動無死地，而謂之「善攝生」矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-27_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-27","order":1,"canonicalText":"愛子者慈於子，重生者慈於身，貴功者慈於事。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-27_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-27","order":2,"canonicalText":"慈母之於弱子也，務致其福，務致其福則事除其禍，事除其禍則思慮熟，思慮熟則得事理，得事理則必成功，必成功則其行之也不疑，不疑之謂勇。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-27_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-27","order":3,"canonicalText":"聖人之於萬事也，盡如慈母之為弱子慮也，故見必行之道，見必行之道則明，其從事亦不疑，不疑之謂勇。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-27_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-27","order":4,"canonicalText":"不疑生於慈，故曰：「慈故能勇。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-27_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-27","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-28_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-28","order":1,"canonicalText":"周公曰：「冬日之閉凍也不固，則春夏之長草木也不茂。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-28_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-28","order":2,"canonicalText":"」天地不能常侈常費，而況於人乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-28_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-28","order":3,"canonicalText":"故萬物必有盛衰，萬事必有弛張，國家必有文武，官治必有賞罰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-28_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-28","order":4,"canonicalText":"是以智士儉用其財則家富，聖人愛寶其神則精盛，人君重戰其卒則民眾。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-28_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-28","order":5,"canonicalText":"民眾則國廣，是以舉之曰：「儉故能廣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-28_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-28","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":1,"canonicalText":"凡物之有形者易裁也，易割也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":2,"canonicalText":"何以論之？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":3,"canonicalText":"有形則有短長，有短長則有小大，有小大則有方圓，有方圓則有堅脆，有堅脆則有輕重，有輕重則有白黑。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":4,"canonicalText":"短長、大小、方圓、堅脆、輕重、白黑之謂理。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":5,"canonicalText":"理定而物易割也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":6,"canonicalText":"故議於大庭而後言則立，權議之士知之矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":7,"canonicalText":"故欲成方圓而隨其規矩，則萬事之功形矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":8,"canonicalText":"而萬物莫不有規矩。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":9,"canonicalText":"議言之士，計會規矩也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":10,"canonicalText":"聖人盡隨於萬物之規矩，故曰：「不敢為天下先。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":11,"canonicalText":"」不敢為天下先則事無不事，功無不功，而議必蓋世，欲無處大官，其可得乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":12,"canonicalText":"處大官之謂為成事長，是以故曰：「不敢為天下先，故能為成事長。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-29_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-29","order":13,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":1,"canonicalText":"慈於子者不敢絕衣食，慈於身者不敢離法度，慈於方圓者不敢舍規矩。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":2,"canonicalText":"故臨兵而慈於士吏則戰勝敵，慈於器械則城堅固。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":3,"canonicalText":"故曰：「慈於戰則勝，以守則固。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":4,"canonicalText":"」夫能自全也而盡隨於萬物之理者，必且有天生。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":5,"canonicalText":"天生也者，生心也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":6,"canonicalText":"故天下之道盡之生也，若以慈衛之也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":7,"canonicalText":"事必萬全，而舉無不當，則謂之寶矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":8,"canonicalText":"故曰：「吾有三寶，持而寶之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-30_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-30","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":1,"canonicalText":"書之所謂大道也者，端道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":2,"canonicalText":"所謂貌施也者，邪道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":3,"canonicalText":"所謂徑大也者，佳麗也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":4,"canonicalText":"佳麗也者，邪道之分也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":5,"canonicalText":"朝甚除也者，獄訟繁也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":6,"canonicalText":"獄訟繁則田荒，田荒則府倉虛，府倉虛則國貧，國貧而民俗淫侈，民俗淫侈則衣食之業絕，衣食之業絕則民不得無飾巧詐，飾巧詐則知採文，知採文之謂服文采。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":7,"canonicalText":"獄訟繁、倉廩虛、而有以淫侈為俗，則國之傷也若以利劍刺之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":8,"canonicalText":"故曰：「帶利劍。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":9,"canonicalText":"」諸夫飾智故以至於傷國者，其私家必富，私家必富，故曰：「資貨有餘。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":10,"canonicalText":"」國有若是者，則愚民不得無術而效之，效之則小盜生。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":11,"canonicalText":"由是觀之，大姦作則小盜隨，大姦唱則小盜和。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":12,"canonicalText":"竽也者，五聲之長者也，故竽先則鍾瑟皆隨，竽唱則諸樂皆和。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-31_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-31","order":13,"canonicalText":"今大姦作則俗之民唱，俗之民唱則小盜必和，故服文采，帶利劍，厭飲食，而貨資有餘者，是之謂盜竽矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":1,"canonicalText":"人無愚智，莫不有趨舍。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":2,"canonicalText":"恬淡平安，莫不知禍福之所由來。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":3,"canonicalText":"得於好惡，怵於淫物，而後變亂。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":4,"canonicalText":"所以然者，引於外物，亂於玩好也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":5,"canonicalText":"恬淡有趨舍之義，平安知禍福之計。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":6,"canonicalText":"而今也玩好變之，外物引之，引之而往，故曰：「拔。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":7,"canonicalText":"」至聖人不然，一建其趨舍，雖見所好之物不能引，不能引之謂不拔。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":8,"canonicalText":"一於其情，雖有可欲之類，神不為動，神不為動之謂不脫。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":9,"canonicalText":"為人子孫者體此道，以守宗廟不滅之謂祭祀不絕。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":10,"canonicalText":"身以積精為德，家以資財為德，鄉國天下皆以民為德。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":11,"canonicalText":"今治身而外物不能亂其精神，故曰：「脩之身，其德乃真。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":12,"canonicalText":"」真者，慎之固也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":13,"canonicalText":"治家，無用之物不能動其計則資有餘，故曰：「脩之家，其德有餘。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":14,"canonicalText":"」治鄉者行此節，則家之有餘者益眾，故曰：「脩之鄉，其德乃長。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":15,"canonicalText":"」治邦者行此節，則鄉之有德者益眾，故曰：「脩之邦，其德乃豐。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-16","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":16,"canonicalText":"」蒞天下者行此節，則民之生莫不受其澤，故曰：「脩之天下，其德乃普。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-17","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":17,"canonicalText":"」脩身者以此別君子小人，治鄉治邦蒞天下者各以此科適觀息耗則萬不失一，故曰：「以身觀身，以家觀家，以鄉觀鄉，以邦觀邦，以天下觀天下，吾奚以知天下之然也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-18","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":18,"canonicalText":"以此。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-22_p-32_s-19","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-22","passageId":"han-fei-zi_ch-22_p-32","order":19,"canonicalText":"」","chunks":[],"tags":[]}]}');export{i as default};
